import { protocolError } from './clip_protocol';

const START_BUFFER_SECONDS = 2;
const TARGET_BUFFER_SECONDS = 10;

const once = (target, eventName) => new Promise((resolve) => {
  target.addEventListener(eventName, resolve, { once: true });
});

const bufferedAhead = (video) => {
  for (let index = 0; index < video.buffered.length; index += 1) {
    if (video.buffered.start(index) <= video.currentTime + 0.05
        && video.buffered.end(index) >= video.currentTime) {
      return video.buffered.end(index) - video.currentTime;
    }
  }
  return 0;
};

class SourceBufferAppendQueue {
  constructor(sourceBuffer) {
    this.sourceBuffer = sourceBuffer;
    this.queue = [];
    this.running = false;
    this.closed = false;
  }

  append(data) {
    if (this.closed) return Promise.reject(protocolError('Append queue closed'));
    return new Promise((resolve, reject) => {
      this.queue.push({ data, resolve, reject });
      this.drain();
    });
  }

  async drain() {
    if (this.running || this.closed) return;
    this.running = true;
    while (this.queue.length && !this.closed) {
      const item = this.queue.shift();
      try {
        if (this.sourceBuffer.updating) await once(this.sourceBuffer, 'updateend');
        this.sourceBuffer.appendBuffer(item.data);
        await once(this.sourceBuffer, 'updateend');
        item.resolve();
      } catch (error) {
        item.reject(error);
      }
    }
    this.running = false;
  }

  clear() {
    const error = protocolError('Pending append cancelled', 'CLIP_APPEND_CANCELLED');
    this.queue.splice(0).forEach((item) => item.reject(error));
  }

  close() {
    this.closed = true;
    this.clear();
  }
}

/** Own one MediaSource attachment and its sequential fragment buffer loop. */
export class MseClipPlayer {
  constructor({ protocol, clipId, videoElement, onState }) {
    this.protocol = protocol;
    this.clipId = String(clipId);
    this.video = videoElement;
    this.onState = onState;
    this.mediaSource = null;
    this.sourceBuffer = null;
    this.appendQueue = null;
    this.objectUrl = null;
    this.metadata = null;
    this.nextFragment = 0;
    this.pendingRequestIds = new Set();
    this.pumping = false;
    this.destroyed = false;
    this.generation = 0;
    this.started = false;
    this.canSeek = false;
    this.onSeeking = () => {
      // Attaching and priming a MediaSource can emit automatic seeking events.
      // Do not let those cancel fragment 0 before startup buffering completes.
      if (!this.canSeek) return;
      this.seek(this.video.currentTime);
    };
    this.onTimeUpdate = () => this.pump();
  }

  async start() {
    if (!window.MediaSource) throw protocolError('Media Source Extensions are unavailable', 'MSE_UNAVAILABLE');
    this.onState?.({ state: 'preparing', clipId: this.clipId });
    const metadataRequest = this.protocol.requestMetadata(this.clipId);
    this.pendingRequestIds.add(metadataRequest.requestId);
    try {
      this.metadata = await metadataRequest.promise;
    } finally {
      this.pendingRequestIds.delete(metadataRequest.requestId);
    }
    if (!window.MediaSource.isTypeSupported(this.metadata.mimeType)) {
      throw protocolError(`Unsupported clip codec: ${this.metadata.mimeType}`, 'MSE_CODEC_UNSUPPORTED');
    }

    this.mediaSource = new MediaSource();
    this.objectUrl = URL.createObjectURL(this.mediaSource);
    this.video.srcObject = null;
    this.video.src = this.objectUrl;
    await once(this.mediaSource, 'sourceopen');
    if (this.destroyed) return;
    this.sourceBuffer = this.mediaSource.addSourceBuffer(this.metadata.mimeType);
    this.sourceBuffer.mode = 'segments';
    this.appendQueue = new SourceBufferAppendQueue(this.sourceBuffer);
    this.video.addEventListener('seeking', this.onSeeking);
    this.video.addEventListener('timeupdate', this.onTimeUpdate);

    const initRequest = this.protocol.requestInit(this.clipId);
    this.pendingRequestIds.add(initRequest.requestId);
    try {
      const init = await initRequest.promise;
      if (!this.destroyed) await this.appendQueue.append(init.data);
    } finally {
      this.pendingRequestIds.delete(initRequest.requestId);
    }
    await this.pump();
  }

  fragmentAt(time) {
    const fragments = Array.isArray(this.metadata?.fragments) ? this.metadata.fragments : [];
    if (fragments.length) {
      const match = fragments.find((fragment) => (
        time >= Number(fragment.startTime)
        && time < Number(fragment.startTime) + Number(fragment.duration)
      ));
      if (match) return Number(match.index);
      if (time >= Number(fragments[fragments.length - 1].startTime)) {
        return Number(fragments[fragments.length - 1].index);
      }
    }
    const duration = Number(this.metadata?.fragmentDuration) || 2;
    return Math.max(0, Math.floor(time / duration));
  }

  async seek(time) {
    if (this.destroyed || !this.sourceBuffer || !this.metadata) return;
    const generation = ++this.generation;
    this.protocol.cancel([...this.pendingRequestIds]);
    this.pendingRequestIds.clear();
    this.appendQueue.clear();
    this.pumping = false;
    this.nextFragment = this.fragmentAt(time);
    try {
      if (this.sourceBuffer.updating) this.sourceBuffer.abort();
      if (this.sourceBuffer.buffered.length) {
        this.sourceBuffer.remove(0, Math.max(Number(this.metadata.duration) || 0, this.video.duration || 0));
        await once(this.sourceBuffer, 'updateend');
      }
      if (!this.destroyed && generation === this.generation) await this.pump();
    } catch (error) {
      if (!['CLIP_REQUEST_CANCELLED', 'CLIP_APPEND_CANCELLED'].includes(error.code)) {
        this.onState?.({ state: 'failed', error });
      }
    }
  }

  async pump() {
    if (this.destroyed || this.pumping || !this.appendQueue) return;
    this.pumping = true;
    const generation = this.generation;
    const fragmentCount = Number(this.metadata.fragmentCount) || 0;
    try {
      while (!this.destroyed && generation === this.generation
          && this.nextFragment < fragmentCount
          && bufferedAhead(this.video) < TARGET_BUFFER_SECONDS) {
        const index = this.nextFragment;
        const request = this.protocol.requestFragment(this.clipId, index);
        this.pendingRequestIds.add(request.requestId);
        let fragment;
        try {
          fragment = await request.promise;
        } finally {
          this.pendingRequestIds.delete(request.requestId);
        }
        if (this.destroyed || generation !== this.generation) return;
        await this.appendQueue.append(fragment.data);
        this.nextFragment = index + 1;
        if (!this.started && (bufferedAhead(this.video) >= START_BUFFER_SECONDS
            || this.nextFragment >= fragmentCount)) {
          this.started = true;
          this.canSeek = true;
          this.video.play().catch(() => {});
          this.onState?.({ state: 'playing', clipId: this.clipId });
        }
      }
      if (this.nextFragment >= fragmentCount
          && this.mediaSource.readyState === 'open'
          && !this.sourceBuffer.updating) {
        this.mediaSource.endOfStream();
      }
    } catch (error) {
      if (!['CLIP_REQUEST_CANCELLED', 'CLIP_APPEND_CANCELLED'].includes(error.code)) {
        this.onState?.({ state: 'failed', error });
        throw error;
      }
    } finally {
      if (generation === this.generation) this.pumping = false;
    }
  }

  destroy() {
    if (this.destroyed) return;
    this.destroyed = true;
    this.generation += 1;
    this.protocol.cancel([...this.pendingRequestIds]);
    this.pendingRequestIds.clear();
    this.video.removeEventListener('seeking', this.onSeeking);
    this.video.removeEventListener('timeupdate', this.onTimeUpdate);
    this.appendQueue?.close();
    try {
      if (this.sourceBuffer?.updating) this.sourceBuffer.abort();
    } catch (_error) {
    }
    this.video.pause();
    this.video.removeAttribute('src');
    this.video.load();
    if (this.objectUrl) URL.revokeObjectURL(this.objectUrl);
  }
}
