import React, { useMemo, useState } from 'react';
import { Camera, KeyRound, Loader2, Play, Plus, RefreshCw, Search, Square } from 'lucide-react';
import { toast } from 'react-hot-toast';

import { api } from '../../api';

const INITIAL_ONVIF_FORM = {
  host: '',
  port: '80',
  username: '',
  password: '',
  timeoutSec: '15',
  profileToken: '',
  cameraName: '',
  resolution: '640x480',
  fps: '7',
  audioEnabled: true,
  keepOnline: true,
};

const getTargetFromDiscoveredDevice = (device = {}) => {
  const fallbackHost = String(device?.ip || '').trim();
  const xaddrs = Array.isArray(device?.xaddrs) ? device.xaddrs : [];

  for (const candidate of xaddrs) {
    const raw = String(candidate || '').trim();
    if (!raw) {
      continue;
    }
    try {
      const parsed = new URL(raw);
      const host = String(parsed.hostname || '').trim() || fallbackHost;
      const port = Number.parseInt(String(parsed.port || '').trim(), 10);
      return {
        host,
        port: Number.isInteger(port) && port >= 1 && port <= 65535 ? String(port) : '',
      };
    } catch (error) {
      // Ignore malformed discovery XAddr entries and continue.
    }
  }

  return { host: fallbackHost, port: '' };
};

function OnvifTab() {
  const [form, setForm] = useState(INITIAL_ONVIF_FORM);
  const [busyAction, setBusyAction] = useState('');
  const [output, setOutput] = useState('No ONVIF operation run yet.');
  const [discovered, setDiscovered] = useState([]);
  const [profiles, setProfiles] = useState([]);
  const [streamUrl, setStreamUrl] = useState('');
  const [createdCamera, setCreatedCamera] = useState(null);
  const [previewUrl, setPreviewUrl] = useState('');

  const setField = (field, value) => {
    setForm((prev) => ({ ...prev, [field]: value }));
  };

  const basePayload = useMemo(() => ({
    host: String(form.host || '').trim(),
    port: Number.parseInt(String(form.port || '').trim(), 10) || 80,
    username: String(form.username || '').trim(),
    password: String(form.password || ''),
  }), [form]);

  const validateLoginPayload = () => {
    if (!basePayload.host) {
      toast.error('Host is required');
      return false;
    }
    if (!basePayload.username) {
      toast.error('Username is required');
      return false;
    }
    if (!basePayload.password) {
      toast.error('Password is required');
      return false;
    }
    if (!Number.isInteger(basePayload.port) || basePayload.port < 1 || basePayload.port > 65535) {
      toast.error('Port must be between 1 and 65535');
      return false;
    }
    return true;
  };

  const runAction = async (actionName, actionFn, successMessage) => {
    setBusyAction(actionName);
    try {
      const response = await actionFn();
      const payload = response?.data || {};
      setOutput(JSON.stringify(payload, null, 2));
      if (successMessage) {
        toast.success(successMessage);
      }
      return payload;
    } catch (error) {
      const detail = error?.response?.data?.detail || error?.message || 'Operation failed';
      setOutput(String(detail));
      toast.error(String(detail));
      return null;
    } finally {
      setBusyAction('');
    }
  };

  const handleDiscovery = async () => {
    const timeout = Math.max(1, Math.min(15, Number.parseInt(String(form.timeoutSec || '').trim(), 10) || 3));
    const payload = await runAction(
      'discover',
      () => api.onvifDiscovery({ timeout_sec: timeout }),
      'Discovery completed'
    );
    if (!payload) return;

    const devices = Array.isArray(payload.devices) ? payload.devices : [];
    setDiscovered(devices);
    if (!form.host && devices.length > 0) {
      setField('host', devices[0].ip || '');
    }
  };

  const handleGetProfiles = async () => {
    if (!validateLoginPayload()) return;
    const payload = await runAction('profiles', () => api.onvifProfiles(basePayload), 'Profiles loaded');
    if (!payload) return;

    const nextProfiles = Array.isArray(payload.profiles) ? payload.profiles : [];
    setProfiles(nextProfiles);
    if (!form.profileToken && nextProfiles.length > 0) {
      setField('profileToken', String(nextProfiles[0]?.token || ''));
    }
  };

  const handleGetStreamUrl = async () => {
    if (!validateLoginPayload()) return;
    const payload = await runAction(
      'stream-url',
      () => api.onvifStreamUrl({
        ...basePayload,
        profile_token: String(form.profileToken || '').trim() || undefined,
      }),
      'Stream URL loaded'
    );
    if (!payload) return;

    const rtsp = payload?.stream?.rtsp_uri_with_auth || payload?.stream?.rtsp_uri || '';
    setStreamUrl(String(rtsp || ''));
  };

  const handleCreateCamera = async () => {
    if (!validateLoginPayload()) return;

    const payload = await runAction(
      'create-camera',
      () => api.onvifCreateCamera({
        ...basePayload,
        profile_token: String(form.profileToken || '').trim() || undefined,
        camera_name: String(form.cameraName || '').trim() || undefined,
        resolution: String(form.resolution || '640x480'),
        fps: Math.max(1, Math.min(60, Number.parseInt(String(form.fps || '').trim(), 10) || 7)),
        audio_enabled: Boolean(form.audioEnabled),
        keep_online: Boolean(form.keepOnline),
        start_stream: true,
      }),
      'Camera created'
    );
    if (!payload) return;

    const camera = payload.camera || null;
    setCreatedCamera(camera);

    const rtsp = payload?.stream?.rtsp_uri_with_auth || payload?.stream?.rtsp_uri || '';
    setStreamUrl(String(rtsp || ''));

    if (camera?.id && payload?.stream_started) {
      setPreviewUrl(api.getCameraMjpegStreamUrl(camera.id));
    }
  };

  const handleLoadCreatedStream = async () => {
    const cameraId = String(createdCamera?.id || '').trim();
    if (!cameraId) {
      toast.error('Create camera first');
      return;
    }

    setBusyAction('load-stream');
    try {
      await api.startCamera(cameraId);
      setPreviewUrl(api.getCameraMjpegStreamUrl(cameraId));
      toast.success('Live stream loaded');
    } catch (error) {
      const detail = error?.response?.data?.detail || error?.message || 'Failed to load stream';
      setOutput(String(detail));
      toast.error(String(detail));
    } finally {
      setBusyAction('');
    }
  };

  const handleStopCreatedStream = async () => {
    const cameraId = String(createdCamera?.id || '').trim();
    if (!cameraId) {
      toast.error('Create camera first');
      return;
    }

    setBusyAction('stop-stream');
    try {
      await api.stopCamera(cameraId);
      setPreviewUrl('');
      toast.success('Live stream stopped');
    } catch (error) {
      const detail = error?.response?.data?.detail || error?.message || 'Failed to stop stream';
      setOutput(String(detail));
      toast.error(String(detail));
    } finally {
      setBusyAction('');
    }
  };

  return (
    <div className="network-panel info-card">
      <div className="info-title admin-title network-panel-title">
        <div className="network-panel-title-main">
          <Camera size={20} />
          <span>ONVIF Manager</span>
        </div>
      </div>

      <div className="network-layout network-layout--onvif">
        <div className="network-card">
          <div className="network-card-title">Discovery</div>

          <div className="network-field-row">
            <span className="network-field-label">Timeout:</span>
            <input
              className="api-endpoint-input"
              type="number"
              min="1"
              max="15"
              value={form.timeoutSec}
              onChange={(event) => setField('timeoutSec', event.target.value)}
            />
          </div>

          <button
            type="button"
            className="network-btn network-btn--accent"
            disabled={Boolean(busyAction)}
            onClick={handleDiscovery}
          >
            {busyAction === 'discover' ? <Loader2 size={13} className="spin" /> : <Search size={13} />}
            Discover
          </button>

          <div className="network-tunnel-list network-onvif-discovery-list" role="list">
            {discovered.length === 0 ? (
              <div className="network-tunnel-empty">No ONVIF device discovered yet</div>
            ) : (
              discovered.map((device, index) => {
                const ip = String(device?.ip || '').trim();
                const xaddrs = Array.isArray(device?.xaddrs) ? device.xaddrs : [];
                return (
                  <button
                    key={`${ip}-${index}`}
                    type="button"
                    className="network-tunnel-item"
                    onClick={() => {
                      const target = getTargetFromDiscoveredDevice(device);
                      const nextHost = target.host || ip;
                      const nextPort = target.port || String(form.port || '').trim();

                      setForm((prev) => ({
                        ...prev,
                        host: nextHost,
                        port: nextPort || prev.port,
                      }));

                      toast.success(
                        nextPort
                          ? `Selected target: ${nextHost}:${nextPort}`
                          : `Selected host: ${nextHost}`
                      );
                    }}
                  >
                    <span className="network-tunnel-index">{index + 1}.</span>
                    <span className="network-tunnel-name">
                      {ip}
                      {xaddrs[0] ? ` | ${xaddrs[0]}` : ''}
                    </span>
                  </button>
                );
              })
            )}
          </div>
        </div>

        <div className="network-card">
          <div className="network-card-title">Login / Profile / Stream URL</div>

          <div className="network-field-row">
            <span className="network-field-label">Host:</span>
            <input
              className="api-endpoint-input"
              placeholder="192.168.0.100"
              value={form.host}
              onChange={(event) => setField('host', event.target.value)}
            />
          </div>

          <div className="network-field-row">
            <span className="network-field-label">Port:</span>
            <input
              className="api-endpoint-input"
              type="number"
              min="1"
              max="65535"
              value={form.port}
              onChange={(event) => setField('port', event.target.value)}
            />
          </div>

          <div className="network-field-row">
            <span className="network-field-label">User:</span>
            <input
              className="api-endpoint-input"
              value={form.username}
              onChange={(event) => setField('username', event.target.value)}
            />
          </div>

          <div className="network-field-row">
            <span className="network-field-label">Password:</span>
            <input
              className="api-endpoint-input"
              type="password"
              autoComplete="new-password"
              value={form.password}
              onChange={(event) => setField('password', event.target.value)}
            />
          </div>

          <div className="network-action-row network-action-row--onvif">
            <button
              type="button"
              className="network-btn"
              disabled={Boolean(busyAction)}
              onClick={handleGetProfiles}
            >
              {busyAction === 'profiles' ? <Loader2 size={13} className="spin" /> : <RefreshCw size={13} />}
              GetProfile
            </button>

            <button
              type="button"
              className="network-btn"
              disabled={Boolean(busyAction)}
              onClick={handleGetStreamUrl}
            >
              {busyAction === 'stream-url' ? <Loader2 size={13} className="spin" /> : <KeyRound size={13} />}
              GetStreamUrl
            </button>
          </div>

          <div className="network-field-row">
            <span className="network-field-label">Profile:</span>
            <select
              className="api-endpoint-select"
              value={form.profileToken}
              onChange={(event) => setField('profileToken', event.target.value)}
            >
              <option value="">Auto (first profile)</option>
              {profiles.map((profile, index) => {
                const token = String(profile?.token || '');
                const name = String(profile?.name || token || `profile-${index + 1}`);
                const size = profile?.width && profile?.height ? `${profile.width}x${profile.height}` : '';
                return (
                  <option key={`${token}-${index}`} value={token}>
                    {size ? `${name} (${size})` : name}
                  </option>
                );
              })}
            </select>
          </div>

          <div className="network-field-row">
            <span className="network-field-label">RTSP URL:</span>
            <input className="api-endpoint-input" value={streamUrl} readOnly />
          </div>

          <div className="network-output">
            <div className="network-output-title">Output</div>
            <pre>{output}</pre>
          </div>
        </div>

        <div className="network-card">
          <div className="network-card-title">Create Camera + Stream</div>

          <div className="network-field-row">
            <span className="network-field-label">Name:</span>
            <input
              className="api-endpoint-input"
              placeholder="optional"
              value={form.cameraName}
              onChange={(event) => setField('cameraName', event.target.value)}
            />
          </div>

          <div className="network-field-row">
            <span className="network-field-label">Resolution:</span>
            <select
              className="api-endpoint-select"
              value={form.resolution}
              onChange={(event) => setField('resolution', event.target.value)}
            >
              <option value="320x240">320x240</option>
              <option value="480x360">480x360</option>
              <option value="640x480">640x480</option>
              <option value="1280x720">1280x720</option>
              <option value="1920x1080">1920x1080</option>
            </select>
          </div>

          <div className="network-field-row">
            <span className="network-field-label">FPS:</span>
            <input
              className="api-endpoint-input"
              type="number"
              min="1"
              max="60"
              value={form.fps}
              onChange={(event) => setField('fps', event.target.value)}
            />
          </div>

          <div className="network-field-row">
            <span className="network-field-label">Audio:</span>
            <input
              type="checkbox"
              checked={form.audioEnabled}
              onChange={(event) => setField('audioEnabled', event.target.checked)}
            />
          </div>

          <div className="network-field-row">
            <span className="network-field-label">Keep online:</span>
            <input
              type="checkbox"
              checked={form.keepOnline}
              onChange={(event) => setField('keepOnline', event.target.checked)}
            />
          </div>

          <div className="network-action-row network-action-row--onvif">
            <button
              type="button"
              className="network-btn network-btn--accent"
              disabled={Boolean(busyAction)}
              onClick={handleCreateCamera}
            >
              {busyAction === 'create-camera' ? <Loader2 size={13} className="spin" /> : <Plus size={13} />}
              Create Camera
            </button>

            <button
              type="button"
              className="network-btn"
              disabled={Boolean(busyAction) || !createdCamera?.id}
              onClick={handleLoadCreatedStream}
            >
              {busyAction === 'load-stream' ? <Loader2 size={13} className="spin" /> : <Play size={13} />}
              Stream
            </button>

            <button
              type="button"
              className="network-btn"
              disabled={Boolean(busyAction) || !createdCamera?.id}
              onClick={handleStopCreatedStream}
            >
              {busyAction === 'stop-stream' ? <Loader2 size={13} className="spin" /> : <Square size={13} />}
              Stop Stream
            </button>
          </div>

          <div className="network-field-row">
            <span className="network-field-label">Camera ID:</span>
            <input className="api-endpoint-input" value={String(createdCamera?.id || '')} readOnly />
          </div>

          <div className="network-onvif-preview">
            {previewUrl ? (
              <img src={previewUrl} alt="ONVIF stream preview" />
            ) : (
              <div className="network-onvif-preview-empty">No stream loaded yet</div>
            )}
          </div>

        </div>
      </div>
    </div>
  );
}

export default OnvifTab;
