import {
  API_ENDPOINT_MODES,
  getApiEndpointSettings,
  setApiEndpointMode,
} from './connection';

// Endpoint failover settings. REACT_APP values can override these at build time.
export const ENDPOINT_PRIORITY_CHECK_INTERVAL_MS =
  Number(process.env.REACT_APP_ENDPOINT_CHECK_INTERVAL_MS) || 180_000;
export const ENDPOINT_HEALTH_TIMEOUT_MS =
  Number(process.env.REACT_APP_ENDPOINT_HEALTH_TIMEOUT_MS) || 2_000;

const DEVICE_ID_STORAGE_KEY = 'nvr_backend_device_id';
const ENDPOINT_PRIORITY = [
  API_ENDPOINT_MODES.LOCAL,
  API_ENDPOINT_MODES.REMOTE_1,
  API_ENDPOINT_MODES.REMOTE_2,
  API_ENDPOINT_MODES.CUSTOM,
];

const getExpectedDeviceId = () => {
  if (typeof window === 'undefined') return '';
  return window.localStorage?.getItem(DEVICE_ID_STORAGE_KEY) || '';
};

const storeExpectedDeviceId = (deviceId) => {
  if (typeof window !== 'undefined' && deviceId) {
    window.localStorage?.setItem(DEVICE_ID_STORAGE_KEY, deviceId);
  }
};

export const getPriorityEndpointCandidates = ({ higherThanMode } = {}) => {
  const settings = getApiEndpointSettings();
  const currentIndex = ENDPOINT_PRIORITY.indexOf(higherThanMode);
  const allowedModes = currentIndex > 0
    ? ENDPOINT_PRIORITY.slice(0, currentIndex)
    : (higherThanMode ? [] : ENDPOINT_PRIORITY);
  const optionsByMode = new Map(settings.options.map(option => [option.value, option]));

  return allowedModes
    .map(mode => optionsByMode.get(mode))
    .filter(option => Boolean(option?.baseUrl));
};

export const probeEndpoint = async (endpoint, timeoutMs = ENDPOINT_HEALTH_TIMEOUT_MS) => {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetch(`${endpoint.baseUrl}/api/health`, {
      method: 'GET',
      cache: 'no-store',
      credentials: 'omit',
      signal: controller.signal,
    });
    if (!response.ok) return null;
    const health = await response.json();
    if (health?.status !== 'ok' || !health?.device_id || health.device_id === 'unknown') {
      return null;
    }
    return { ...endpoint, deviceId: health.device_id };
  } catch (_) {
    return null;
  } finally {
    clearTimeout(timeoutId);
  }
};

export const selectPreferredApiEndpoint = async ({ higherPriorityOnly = false } = {}) => {
  const settings = getApiEndpointSettings();
  const candidates = getPriorityEndpointCandidates({
    higherThanMode: higherPriorityOnly ? settings.mode : undefined,
  });
  if (candidates.length === 0) return null;

  // Probe concurrently so an unavailable local URL does not delay remote access.
  const results = await Promise.all(candidates.map(candidate => probeEndpoint(candidate)));
  const expectedDeviceId = getExpectedDeviceId();
  const selected = results.find(result => (
    result && (!expectedDeviceId || result.deviceId === expectedDeviceId)
  ));
  if (!selected) return null;

  storeExpectedDeviceId(selected.deviceId);
  const changed = selected.value !== settings.mode || selected.baseUrl !== settings.baseUrl;
  if (changed) {
    setApiEndpointMode(selected.value);
  }
  return { ...selected, changed };
};
