/**
 * ZoneManager — always-visible zone editor.
 *
 * Layout:
 *   ┌─ zone chips (+ New | Zone A ✕ | Zone B ✕ | …) ─────────────────────┐
 *   ├─ form bar (name · color · type · hit mode · ▶/■ camera) ────┤
 *   └─ ZoneEditor canvas with left sidebar ──────────────────────────────┘
 *
 * Props:
 *   camera     {object}  Camera object (.id, .name, .status)
 *   streamUrl  {string}  MJPEG URL for the drawing canvas background
 *   onClose    {fn}
 */

import React, { useCallback, useEffect, useState } from 'react';
import { toast } from 'react-hot-toast';
import zonesApi from '../../zonesApi';
import { api } from '../../api';
import ZoneEditor from './ZoneEditor';
import './zones.css';

const ZONE_TYPES = [
  { value: 'door',        label: 'Door' },
  { value: 'active_mask', label: 'Mask' },
  { value: 'active_zone', label: 'Zone' },
];

const HIT_MODES = [
  { value: 'centroid', label: 'Centroid' },
  { value: 'bbox_any', label: 'Any bbox corner' },
];

const DEFAULT_COLORS = {
  door: '#fbbf24',
  active_zone: '#ef4444',
  active_mask: '#22c55e',
};

const freshForm = (zones, zoneType = 'active_zone') => ({
  name: `Zone ${zones.length + 1}`,
  color: DEFAULT_COLORS[zoneType] || DEFAULT_COLORS.active_zone,
  zone_type: zoneType,
  hit_mode: 'bbox_any',
  entry_edge_index: null,
  entry_line: null,
  entry_direction_point: null,
});

const ZoneManager = ({ camera, streamUrl, onClose }) => {
  const [zones,        setZones]        = useState([]);
  const [loading,      setLoading]      = useState(true);
  const [editingZone,  setEditingZone]  = useState(null);  // null = new zone
  const [form,         setForm]         = useState(freshForm([]));
  const [cameraStatus, setCameraStatus] = useState(camera.status || 'offline');
  const [camBusy,      setCamBusy]      = useState(false);

  // Sync local status when parent prop updates (e.g. camera stopped elsewhere)
  useEffect(() => { setCameraStatus(camera.status || 'offline'); }, [camera.status]);

  // ── load ─────────────────────────────────────────────────────────────────

  const fetchZones = useCallback(async () => {
    try {
      setLoading(true);
      const { data } = await zonesApi.getCameraZones(camera.id);
      setZones(data.zones || []);
    } catch {
      toast.error('Failed to load zones');
    } finally {
      setLoading(false);
    }
  }, [camera.id]);

  useEffect(() => { fetchZones(); }, [fetchZones]);

  // ── zone selection ────────────────────────────────────────────────────────

  const selectNew = (currentZones) => {
    setEditingZone(null);
    setForm(freshForm(currentZones ?? zones));
  };

  const selectNewWithType = (zoneType) => {
    setEditingZone(null);
    setForm(freshForm(zones, zoneType));
  };

  const selectZone = (zone) => {
    setEditingZone(zone);
    setForm({
      name: zone.name,
      color: zone.color,
      zone_type: zone.zone_type,
      hit_mode: zone.hit_mode,
      entry_edge_index: zone.entry_edge_index ?? null,
      entry_line: zone.entry_line ?? null,
      entry_direction_point: zone.entry_direction_point ?? null,
    });
  };

  const handleEditSelectionChange = (e) => {
    const zoneId = e.target.value;
    if (!zoneId) {
      selectNew();
      return;
    }
    const zone = zones.find((z) => String(z.zone_id) === zoneId);
    if (zone) selectZone(zone);
  };

  // ── save ──────────────────────────────────────────────────────────────────

  const handleEditorSave = async (geometry, updatedOtherZones) => {
    const editedZoneId = editingZone?.zone_id || null;
    const payload = form.zone_type === 'door'
      ? {
          ...form,
          polygons: [],
          entry_edge_index: null,
          entry_line: geometry.entryLine,
          entry_direction_point: geometry.entryDirectionPoint,
        }
      : { ...form, polygons: geometry };
    try {
      if (editingZone) {
        await zonesApi.updateZone(camera.id, editingZone.zone_id, payload);
      } else {
        await zonesApi.createZone(camera.id, payload);
      }
      const changedOtherZones = updatedOtherZones || [];
      if (changedOtherZones.length > 0) {
        await Promise.all(
          changedOtherZones.map((oz) => (
            oz.zone_type === 'door'
              ? zonesApi.updateZone(camera.id, oz.zone_id, {
                  entry_line: oz.entry_line,
                  entry_direction_point: oz.entry_direction_point,
                })
              : zonesApi.updateZone(camera.id, oz.zone_id, { polygons: oz.polygons })
          ))
        );
      }
      toast.success(editingZone ? 'Zone updated' : 'Zone created');
      const { data } = await zonesApi.getCameraZones(camera.id);
      const newZones = data.zones || [];
      setZones(newZones);
      window.dispatchEvent(new CustomEvent('zones:updated', {
        detail: { cameraId: camera.id, zones: newZones },
      }));
      if (editedZoneId) {
        const refreshed = newZones.find(z => z.zone_id === editedZoneId);
        if (refreshed) {
          selectZone(refreshed);
        }
      } else {
        setForm(freshForm(newZones)); // reset form for next new zone, keep editingZone=null
      }
    } catch {
      toast.error('Failed to save zone');
    }
  };

  // ── delete / toggle ───────────────────────────────────────────────────────

  const handleDelete = async (zone) => {
    if (!window.confirm(`Delete zone "${zone.name}"?`)) return;
    try {
      await zonesApi.deleteZone(camera.id, zone.zone_id);
      toast.success('Zone deleted');
      const { data } = await zonesApi.getCameraZones(camera.id);
      const newZones = data.zones || [];
      setZones(newZones);
      window.dispatchEvent(new CustomEvent('zones:updated', {
        detail: { cameraId: camera.id, zones: newZones },
      }));
      if (editingZone?.zone_id === zone.zone_id) selectNew(newZones);
    } catch {
      toast.error('Failed to delete zone');
    }
  };



  // ── camera start / stop  ──────────────────────────────────────────────────

  const handleStartCamera = async () => {
    setCamBusy(true);
    try {
      await api.startCamera(camera.id);
      setCameraStatus('online');
      toast.success('Camera started');
    } catch {
      toast.error('Failed to start camera');
    } finally {
      setCamBusy(false);
    }
  };

  const handleStopCamera = async () => {
    setCamBusy(true);
    try {
      await api.stopCamera(camera.id);
      setCameraStatus('offline');
      toast.success('Camera stopped');
    } catch {
      toast.error('Failed to stop camera');
    } finally {
      setCamBusy(false);
    }
  };

  const isOnline = cameraStatus === 'online' || cameraStatus === 'recording';
  // Only feed a live stream URL when the camera is actually running
  const activeStreamUrl = isOnline ? streamUrl : null;

  // ── render ────────────────────────────────────────────────────────────────

  return (
    <div className="zone-manager">

      {/* ── zone chips row ── */}
      <div className="zone-chip-row">
        {/* ── add-type buttons ── */}
        <button
          className="zone-chip zone-chip--add zone-chip--add-door"
          onClick={() => selectNewWithType('door')}
          title="Add a door zone"
        >
          🚪 Add door
        </button>
        <button
          className="zone-chip zone-chip--add zone-chip--add-zone"
          onClick={() => selectNewWithType('active_zone')}
          title="Add a zone"
        >
          ＋ Add zone
        </button>
        <button
          className="zone-chip zone-chip--add zone-chip--add-mask"
          onClick={() => selectNewWithType('active_mask')}
          title="Add a mask"
        >
          ▦ Add mask
        </button>

        {loading && <span style={{ fontSize: 11, color: '#78909c', padding: '0 6px' }}>Loading…</span>}

        {zones.map((zone) => (
          <div
            key={zone.zone_id}
            className={`zone-chip ${editingZone?.zone_id === zone.zone_id ? 'zone-chip--active' : ''}`}
          >
            <span className="zone-chip__dot" style={{ background: zone.color }} />
            <span className="zone-chip__name" onClick={() => selectZone(zone)}>
              {zone.name}
            </span>
            <button
              className="zone-chip__btn zone-chip__btn--del"
              title="Delete zone"
              onClick={(e) => { e.stopPropagation(); handleDelete(zone); }}
            >
              ✕
            </button>
          </div>
        ))}
      </div>

      {/* ── form bar ── */}
      <div className="zone-form zone-form--bar">
        <div className="zone-form__field">
          <label>Zone name</label>
          <input
            type="text"
            style={{ width: 130 }}
            value={form.name}
            onChange={(e) => setForm({ ...form, name: e.target.value })}
          />
        </div>
        <div className="zone-form__field">
          <label>Colour</label>
          <input
            type="color"
            value={form.color}
            onChange={(e) => setForm({ ...form, color: e.target.value })}
          />
        </div>
        <div className="zone-form__field">
          <label className="zone-form__label zone-form__label--highlight">Edit Zone</label>
          <select value={editingZone?.zone_id || ''} onChange={handleEditSelectionChange}>
            <option value="">Background (new zone)</option>
            {zones.map((z) => (
              <option key={z.zone_id} value={z.zone_id}>{z.name}</option>
            ))}
          </select>
        </div>
        <div className="zone-form__field">
          <label>Type</label>
          <select
            value={form.zone_type}
            onChange={(e) => setForm({
              ...form,
              zone_type: e.target.value,
              color: DEFAULT_COLORS[e.target.value] || DEFAULT_COLORS.active_zone,
              entry_edge_index: null,
              entry_line: e.target.value === 'door' ? form.entry_line : null,
              entry_direction_point: e.target.value === 'door' ? form.entry_direction_point : null,
            })}
          >
            {ZONE_TYPES.map((t) => <option key={t.value} value={t.value}>{t.label}</option>)}
          </select>
        </div>
        <div className="zone-form__field">
          <label>Hit mode</label>
          <select
            value={form.hit_mode}
            onChange={(e) => setForm({ ...form, hit_mode: e.target.value })}
            disabled={form.zone_type === 'active_mask'}
          >
            {HIT_MODES.map((m) => <option key={m.value} value={m.value}>{m.label}</option>)}
          </select>
        </div>
        {form.zone_type === 'door' && (
          <div className="zone-form__field">
            <label>Door</label>
            <span style={{ fontSize: 11, color: '#546e7a', whiteSpace: 'nowrap' }}>Line + Entry -&gt; toggle</span>
          </div>
        )}

        {/* ── camera start / stop ── */}
        <div className="zone-form__field zone-form__field--cam">
          <label>{camera.name || camera.id}</label>
          <button
            className={`zone-btn ${isOnline ? 'zone-btn--cam-stop' : 'zone-btn--cam-start'}`}
            onClick={isOnline ? handleStopCamera : handleStartCamera}
            disabled={camBusy}
            title={isOnline ? 'Stop camera stream' : 'Start camera stream'}
          >
            {camBusy ? '…' : (isOnline ? '■ Stop' : '▶ Start')}
          </button>
        </div>
      </div>

      {/* ── editor canvas ── */}
      <ZoneEditor
        streamUrl={activeStreamUrl}
        zones={zones}
        editZone={editingZone}
        zoneType={form.zone_type}
        color={form.color}
        resolution={camera.resolution}
        isDoor={form.zone_type === 'door'}
        entryLine={form.zone_type === 'door' ? form.entry_line : null}
        entryDirectionPoint={form.zone_type === 'door' ? form.entry_direction_point : null}
        onSave={handleEditorSave}
        onCancel={() => selectNew(zones)}
      />

      {onClose && (
        <button className="zone-btn" style={{ alignSelf: 'flex-start', marginTop: 6 }} onClick={onClose}>
          ← Back
        </button>
      )}
    </div>
  );
};

export default ZoneManager;
