import { transportApi } from './api';
import { buildIceServers, waitForIceGathering } from './webrtc';

const WEBRTC_RETRY_DELAY_MS = 60000;
const WEBSOCKET_RECONNECT_DELAY_MS = 2000;

const connectWebRtcDataChannel = async ({
  onMessage,
  onConnected,
  onUnavailable,
  includeRecordingEvents,
}) => {
  const config = await transportApi.getIceConfig();
  const peer = new RTCPeerConnection({ iceServers: buildIceServers(config) });
  const events = peer.createDataChannel('events', { ordered: true });
  const metrics = peer.createDataChannel('metrics', { ordered: false, maxRetransmits: 0 });
  const control = peer.createDataChannel('control', { ordered: true });
  let sessionId = null;
  let closed = false;

  const handleMessage = (event) => {
    try {
      onMessage(JSON.parse(event.data));
    } catch (_error) {
    }
  };
  events.onmessage = handleMessage;
  metrics.onmessage = handleMessage;
  control.onopen = () => {
    control.send(JSON.stringify({
      type: 'subscribe',
      camera_ids: [],
      recordings: Boolean(includeRecordingEvents),
    }));
    onConnected();
  };

  const close = () => {
    if (closed) return;
    closed = true;
    peer.close();
    if (sessionId) transportApi.stopWebRtcDataChannel(sessionId).catch(() => {});
  };

  peer.onconnectionstatechange = () => {
    if (!closed && ['failed', 'disconnected'].includes(peer.connectionState)) {
      close();
      onUnavailable();
    }
  };

  try {
    const offer = await peer.createOffer();
    await peer.setLocalDescription(offer);
    await waitForIceGathering(peer);
    const answer = await transportApi.startWebRtcDataChannel(peer.localDescription.sdp);
    sessionId = answer.session_id;
    await peer.setRemoteDescription({ type: 'answer', sdp: answer.sdp });
    return close;
  } catch (error) {
    close();
    throw error;
  }
};

export const connectApplicationDataChannel = ({
  onMessage,
  onTransportChange = () => {},
  includeRecordingEvents = false,
}) => {
  let cancelled = false;
  let connectingWebRtc = false;
  let closeWebRtc = null;
  let websocket = null;
  let webRtcRetryTimer = null;
  let websocketReconnectTimer = null;
  let activeTransport = '--';

  const reportTransport = (transport) => {
    if (activeTransport === transport) return;
    activeTransport = transport;
    onTransportChange(transport);
  };

  const closeWebSocket = () => {
    if (!websocket) return;
    const socket = websocket;
    websocket = null;
    socket.onclose = null;
    socket.close();
    if (activeTransport === 'ws') reportTransport('--');
  };

  const clearWebRtcRetry = () => {
    if (!webRtcRetryTimer) return;
    window.clearTimeout(webRtcRetryTimer);
    webRtcRetryTimer = null;
  };

  const scheduleWebRtcRetry = () => {
    if (cancelled || closeWebRtc || connectingWebRtc || webRtcRetryTimer) return;
    webRtcRetryTimer = window.setTimeout(() => {
      webRtcRetryTimer = null;
      startWebRtc();
    }, WEBRTC_RETRY_DELAY_MS);
  };

  const startWebSocket = () => {
    if (cancelled || closeWebRtc || websocket) return;
    const socket = new WebSocket(
      transportApi.getDataChannelWebSocketUrl(includeRecordingEvents),
    );
    websocket = socket;
    socket.onopen = () => {
      if (!cancelled && websocket === socket && !closeWebRtc) {
        reportTransport('ws');
      }
    };
    socket.onmessage = (event) => {
      try {
        onMessage(JSON.parse(event.data));
      } catch (_error) {
      }
    };
    socket.onclose = () => {
      if (websocket === socket) websocket = null;
      if (activeTransport === 'ws') reportTransport('--');
      if (cancelled || closeWebRtc || websocketReconnectTimer) return;
      websocketReconnectTimer = window.setTimeout(() => {
        websocketReconnectTimer = null;
        startWebSocket();
      }, WEBSOCKET_RECONNECT_DELAY_MS);
    };
    scheduleWebRtcRetry();
  };

  const handleWebRtcUnavailable = () => {
    closeWebRtc = null;
    reportTransport('--');
    startWebSocket();
    scheduleWebRtcRetry();
  };

  async function startWebRtc() {
    if (cancelled || closeWebRtc || connectingWebRtc) return;
    connectingWebRtc = true;
    try {
      const close = await connectWebRtcDataChannel({
        onMessage,
        onConnected: () => {
          closeWebSocket();
          reportTransport('wr');
        },
        onUnavailable: handleWebRtcUnavailable,
        includeRecordingEvents,
      });
      if (cancelled) {
        close();
        return;
      }
      closeWebRtc = close;
      clearWebRtcRetry();
    } catch (_error) {
      reportTransport('--');
      startWebSocket();
    } finally {
      connectingWebRtc = false;
      if (!closeWebRtc) scheduleWebRtcRetry();
    }
  }

  startWebRtc();

  return () => {
    cancelled = true;
    clearWebRtcRetry();
    if (websocketReconnectTimer) window.clearTimeout(websocketReconnectTimer);
    closeWebSocket();
    if (closeWebRtc) closeWebRtc();
    reportTransport('--');
  };
};
