export const API_ENDPOINT_MODES = {
  CURRENT: 'current',
  LOCAL: 'local',
  LOCAL_ETH0: 'local_eth0',
  LOCAL_WLAN0: 'local_wlan0',
  REMOTE: 'remote',
  REMOTE_CF: 'remote_cf',
  REMOTE_TS: 'remote_ts',
  REMOTE_RS_FP: 'remote_rs_fp',
  REMOTE_1: 'remote_1',
  REMOTE_2: 'remote_2',
  CUSTOM: 'custom',
};

export const LOCAL_API_BASE_URL = 'http://localhost:9001';
export const REMOTE_API_BASE_URL = 'http://100.68.2.123:9001';

const API_ENDPOINT_MODE_KEY = 'nvr_api_endpoint_mode';
const CUSTOM_API_BASE_URL_KEY = 'nvr_custom_api_base_url';
const DISCOVERED_API_ENDPOINTS_KEY = 'nvr_discovered_api_endpoints';
const LOCAL_DEVICE_ID_KEY = 'nvr_local_device_id';

const isBrowser = () => typeof window !== 'undefined' && typeof window.localStorage !== 'undefined';

const getStoredValue = (key) => {
  if (!isBrowser()) {
    return null;
  }
  return window.localStorage.getItem(key);
};

const setStoredValue = (key, value) => {
  if (isBrowser()) {
    window.localStorage.setItem(key, value);
  }
};

const trimTrailingSlashes = (value) => value.replace(/\/+$/, '');

export const getCurrentApiBaseUrl = () => {
  if (typeof window === 'undefined' || !window.location?.origin) {
    return LOCAL_API_BASE_URL;
  }
  return trimTrailingSlashes(window.location.origin);
};

export const normalizeApiBaseUrl = (value) => {
  const raw = String(value || '').trim();
  if (!raw) {
    throw new Error('Enter a backend URL.');
  }

  const withProtocol = /^[a-z][a-z\d+\-.]*:\/\//i.test(raw) ? raw : `http://${raw}`;
  let parsed;
  try {
    parsed = new URL(withProtocol);
  } catch (error) {
    throw new Error('Enter a valid backend URL, for example http://192.168.1.10:9001.');
  }

  if (!['http:', 'https:'].includes(parsed.protocol)) {
    throw new Error('Only HTTP and HTTPS backend URLs are allowed.');
  }
  if (!parsed.hostname) {
    throw new Error('Backend URL must include a host.');
  }
  if (parsed.username || parsed.password) {
    throw new Error('Do not include usernames or passwords in the backend URL.');
  }

  return trimTrailingSlashes(parsed.origin);
};

export const getApiEndpointMode = () => {
  const mode = getStoredValue(API_ENDPOINT_MODE_KEY);
  if ([API_ENDPOINT_MODES.CURRENT, API_ENDPOINT_MODES.LOCAL_ETH0, API_ENDPOINT_MODES.LOCAL_WLAN0].includes(mode)) {
    return API_ENDPOINT_MODES.LOCAL;
  }
  if ([API_ENDPOINT_MODES.REMOTE, API_ENDPOINT_MODES.REMOTE_CF, API_ENDPOINT_MODES.REMOTE_TS].includes(mode)) {
    return API_ENDPOINT_MODES.REMOTE_1;
  }
  if (mode === API_ENDPOINT_MODES.REMOTE_RS_FP) {
    return API_ENDPOINT_MODES.REMOTE_2;
  }

  const supportedModes = [
    API_ENDPOINT_MODES.LOCAL,
    API_ENDPOINT_MODES.REMOTE_1,
    API_ENDPOINT_MODES.REMOTE_2,
    API_ENDPOINT_MODES.CUSTOM,
  ];
  return supportedModes.includes(mode) ? mode : API_ENDPOINT_MODES.LOCAL;
};

export const getCustomApiBaseUrl = () => getStoredValue(CUSTOM_API_BASE_URL_KEY) || '';

export const normalizeLocalDeviceId = (value) => {
  const raw = String(value || '').trim();
  if (!/^\d{1,4}$/.test(raw) || Number(raw) < 1 || Number(raw) > 9999) {
    throw new Error('Device ID must be a number from 1 to 9999.');
  }
  return String(Number(raw)).padStart(4, '0');
};

export const getLocalDeviceId = () => getStoredValue(LOCAL_DEVICE_ID_KEY) || '';

export const getLocalApiBaseUrl = (deviceId = getLocalDeviceId()) => {
  if (!deviceId) return '';
  const normalizedId = normalizeLocalDeviceId(deviceId);
  return `http://secai-box-274-0825-${normalizedId}.local:3001`;
};

export const setLocalDeviceId = (value) => {
  const normalizedId = normalizeLocalDeviceId(value);
  setStoredValue(LOCAL_DEVICE_ID_KEY, normalizedId);
  setStoredValue(API_ENDPOINT_MODE_KEY, API_ENDPOINT_MODES.LOCAL);
  return getLocalApiBaseUrl(normalizedId);
};

const getDiscoveredApiEndpoints = () => {
  const raw = getStoredValue(DISCOVERED_API_ENDPOINTS_KEY);
  if (!raw) {
    return {};
  }
  try {
    return JSON.parse(raw) || {};
  } catch (error) {
    return {};
  }
};

const hostToApiBaseUrl = (value, { protocol = 'http', defaultPort = '9001' } = {}) => {
  const raw = String(value || '').trim();
  if (!raw) {
    return '';
  }
  if (/^[a-z][a-z\d+\-.]*:\/\//i.test(raw)) {
    return normalizeApiBaseUrl(raw);
  }

  const hasPort = /:\d+$/.test(raw);
  const host = hasPort || !defaultPort ? raw : `${raw}:${defaultPort}`;
  return normalizeApiBaseUrl(`${protocol}://${host}`);
};

const safeHostToApiBaseUrl = (value, options) => {
  try {
    return hostToApiBaseUrl(value, options);
  } catch (error) {
    return '';
  }
};

const localPathToApiBaseUrl = (value) => {
  const raw = String(value || '').trim();
  if (!raw) return '';
  if (/^[a-z][a-z\d+\-.]*:\/\//i.test(raw)) {
    return safeHostToApiBaseUrl(raw);
  }

  const match = raw.match(/^([^:]+)(?::(\d+))?$/);
  if (!match) return '';
  const hostname = match[1].toLowerCase().endsWith('.local')
    ? match[1]
    : `${match[1]}.local`;
  return safeHostToApiBaseUrl(`${hostname}:${match[2] || '3001'}`, { defaultPort: '' });
};

export const setDiscoveredApiEndpoints = (networkEndpoints = {}) => {
  const discovered = {
    [API_ENDPOINT_MODES.LOCAL]: localPathToApiBaseUrl(networkEndpoints.local_path),
    [API_ENDPOINT_MODES.LOCAL_ETH0]: safeHostToApiBaseUrl(networkEndpoints.local_wireless_ip),
    [API_ENDPOINT_MODES.LOCAL_WLAN0]: safeHostToApiBaseUrl(networkEndpoints.local_ethernet_ip),
    [API_ENDPOINT_MODES.REMOTE_CF]: safeHostToApiBaseUrl(
      networkEndpoints.cloudflared_hostname,
      { protocol: 'https', defaultPort: '' }
    ),
    [API_ENDPOINT_MODES.REMOTE_TS]: safeHostToApiBaseUrl(networkEndpoints.tailscale_ip),
    [API_ENDPOINT_MODES.REMOTE_RS_FP]: safeHostToApiBaseUrl(networkEndpoints.rs_fp_ip),
    [API_ENDPOINT_MODES.REMOTE_1]: safeHostToApiBaseUrl(
      networkEndpoints.cloudflared_hostname,
      { protocol: 'https', defaultPort: '' }
    ),
    [API_ENDPOINT_MODES.REMOTE_2]: safeHostToApiBaseUrl(networkEndpoints.rs_fp_ip),
  };
  setStoredValue(DISCOVERED_API_ENDPOINTS_KEY, JSON.stringify(discovered));
  return discovered;
};

export const getApiBaseUrlForMode = (mode = getApiEndpointMode()) => {
  const discovered = getDiscoveredApiEndpoints();
  if (discovered[mode]) {
    return discovered[mode];
  }
  if (mode === API_ENDPOINT_MODES.CURRENT) {
    return getCurrentApiBaseUrl();
  }
  if (mode === API_ENDPOINT_MODES.LOCAL) {
    return getLocalApiBaseUrl() || getCurrentApiBaseUrl();
  }
  if (mode === API_ENDPOINT_MODES.REMOTE) {
    return REMOTE_API_BASE_URL;
  }
  if (mode === API_ENDPOINT_MODES.CUSTOM) {
    const customBaseUrl = getCustomApiBaseUrl();
    if (customBaseUrl) {
      return customBaseUrl;
    }
  }
  return LOCAL_API_BASE_URL;
};

export const getApiBaseUrl = () => getApiBaseUrlForMode();

export const setApiEndpointMode = (mode) => {
  const normalizedMode = Object.values(API_ENDPOINT_MODES).includes(mode)
    ? mode
    : API_ENDPOINT_MODES.CURRENT;
  setStoredValue(API_ENDPOINT_MODE_KEY, normalizedMode);
  return getApiBaseUrlForMode(normalizedMode);
};

export const setCustomApiBaseUrl = (value) => {
  const normalized = normalizeApiBaseUrl(value);
  setStoredValue(CUSTOM_API_BASE_URL_KEY, normalized);
  setStoredValue(API_ENDPOINT_MODE_KEY, API_ENDPOINT_MODES.CUSTOM);
  return normalized;
};

export const getApiEndpointSettings = () => {
  const mode = getApiEndpointMode();
  const discovered = getDiscoveredApiEndpoints();
  const customBaseUrl = getCustomApiBaseUrl();
  const discoveredModes = [
    API_ENDPOINT_MODES.LOCAL,
    API_ENDPOINT_MODES.LOCAL_ETH0,
    API_ENDPOINT_MODES.LOCAL_WLAN0,
    API_ENDPOINT_MODES.REMOTE_CF,
    API_ENDPOINT_MODES.REMOTE_TS,
    API_ENDPOINT_MODES.REMOTE_RS_FP,
    API_ENDPOINT_MODES.REMOTE_1,
    API_ENDPOINT_MODES.REMOTE_2,
  ];
  const localDeviceId = getLocalDeviceId();
  const localBaseUrl = discovered[API_ENDPOINT_MODES.LOCAL] || getLocalApiBaseUrl(localDeviceId);
  return {
    mode,
    baseUrl: mode === API_ENDPOINT_MODES.LOCAL
      ? (localBaseUrl || getCurrentApiBaseUrl())
      : (discoveredModes.includes(mode) ? (discovered[mode] || '') : getApiBaseUrlForMode(mode)),
    customBaseUrl,
    localDeviceId,
    localPathBaseUrl: discovered[API_ENDPOINT_MODES.LOCAL] || '',
    options: [
      {
        value: API_ENDPOINT_MODES.LOCAL,
        label: 'Local',
        baseUrl: localBaseUrl,
      },
      { value: API_ENDPOINT_MODES.REMOTE_1, label: 'Remote-1', baseUrl: discovered[API_ENDPOINT_MODES.REMOTE_1] || '' },
      { value: API_ENDPOINT_MODES.REMOTE_2, label: 'Remote-2', baseUrl: discovered[API_ENDPOINT_MODES.REMOTE_2] || '' },
      {
        value: API_ENDPOINT_MODES.CUSTOM,
        label: 'Custom',
        baseUrl: customBaseUrl,
      },
    ],
  };
};

export const isLocalHostname = (hostname) => {
  const normalized = String(hostname || '').toLowerCase();
  if (!normalized) return false;
  if (['localhost', '::1'].includes(normalized)) return true;
  if (/^127\./.test(normalized)) return true;
  if (/^100\./.test(normalized)) return true;
  if (/^192\.168\./.test(normalized)) return true;
  /*if (/^172\.(1[6-9]|2\d|3[0-1])\./.test(normalized)) return true;*/
  if (normalized.endsWith('.local')) return true;
  return false;
};

export const isLocalApiEndpoint = (endpoint) => {
  const mode = endpoint?.mode;
  if ([API_ENDPOINT_MODES.LOCAL, API_ENDPOINT_MODES.LOCAL_ETH0, API_ENDPOINT_MODES.LOCAL_WLAN0].includes(mode)) {
    return true;
  }
  if ([API_ENDPOINT_MODES.REMOTE, API_ENDPOINT_MODES.REMOTE_CF, API_ENDPOINT_MODES.REMOTE_TS, API_ENDPOINT_MODES.REMOTE_RS_FP, API_ENDPOINT_MODES.REMOTE_1, API_ENDPOINT_MODES.REMOTE_2].includes(mode)) {
    return false;
  }
  try {
    const parsed = new URL(endpoint?.baseUrl || getApiEndpointSettings().baseUrl);
    return isLocalHostname(parsed.hostname);
  } catch (error) {
    return false;
  }
};

export const getMinimalModeState = ({ minimalModeOverride = null, apiEndpoint }) => {
  const apiEndpointIsLocal = isLocalApiEndpoint(apiEndpoint);
  const automaticMinimalMode = !apiEndpointIsLocal;
  return {
    apiEndpointIsLocal,
    automaticMinimalMode,
    effectiveMinimalMode: typeof minimalModeOverride === 'boolean'
      ? minimalModeOverride
      : automaticMinimalMode,
  };
};

const STREAM_MODE_POLICIES = {
  minimal: ['webrtc'],
  full: ['mjpeg'],
};

const PLAYBACK_MODE_POLICIES = {
  minimal: ['p2p', 'mse'],
  full: ['file'],
};

export const setupStreamingFeatures = ({ minimalMode }) => {
  const activeStreamModes = minimalMode ? STREAM_MODE_POLICIES.minimal : STREAM_MODE_POLICIES.full;
  const activePlaybackModes = minimalMode ? PLAYBACK_MODE_POLICIES.minimal : PLAYBACK_MODE_POLICIES.full;

  return {
    activeStreamModes,
    activePlaybackModes,
    streamMode: activeStreamModes[0],
    playbackMode: activePlaybackModes[0],
  };
};
