import React, { useEffect, useState } from 'react';
import { Plus, Save, Trash2, RefreshCw } from 'lucide-react';
import { toast } from 'react-hot-toast';
import { api } from '../../api';
import { CameraForm, DEFAULT_CAMERA_FORM } from '../CameraList/CameraForm';

const FPS_OPTIONS = [5, 10, 15, 20, 25, 30];
const RESOLUTION_OPTIONS = [
  { value: '640x480', label: '640x480 (VGA)' },
  { value: '1280x720', label: '1280x720 (HD)' },
  { value: '1920x1080', label: '1920x1080 (Full HD)' },
  { value: '480x360', label: '480x360' },
  { value: '320x240', label: '320x240' },
];

const PARAM_ROW_STYLE = { alignItems: 'center' };
const PARAM_LABEL_STYLE = { minWidth: 180 };
const PARAM_CONTROL_STYLE = { display: 'flex', alignItems: 'center', gap: 8, marginLeft: 'auto' };
const PARAM_INPUT_STYLE = { width: 132 };
const PARAM_UNIT_STYLE = { minWidth: 34, textAlign: 'right' };
const normalizeClipPlaybackMode = (mode) => (
  String(mode || '').toLowerCase() === 'webrtc' ? 'p2p' : String(mode || '').toLowerCase()
);

const SystemSettings = ({ cameras = [], setCameras, onSettingsUpdated }) => {
  const [settings, setSettings] = useState({
    live_stream_mode: 'mjpeg',
    clip_playback_mode: 'file',
    enable_yolox: true,
    enable_pann: false,
    max_stk_amp: 50,
    max_osc_count: 20,
    waiting_duration_threshold: 60,
    waiting_zone_threshold: 0.5,
  });
  const [cameraRows, setCameraRows] = useState({});
  const [showAddCameraModal, setShowAddCameraModal] = useState(false);
  const [newCamera, setNewCamera] = useState({ ...DEFAULT_CAMERA_FORM });
  const [savingCameraId, setSavingCameraId] = useState('');
  const [deletingCameraId, setDeletingCameraId] = useState('');
  const [applyingCameraId, setApplyingCameraId] = useState('');
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    const nextRows = {};
    cameras.forEach((camera) => {
      nextRows[camera.id] = {
        name: camera.name || '',
        camera_type: camera.camera_type || 'rtsp',
        source: camera.source || '',
        resolution: camera.resolution || '1920x1080',
        fps: Number(camera.fps) || 30,
        audio_enabled: Boolean(camera.audio_enabled),
        keep_online: camera.keep_online !== false,
        max_recordings: Number(camera.max_recordings || 3000),
        sensitivity: camera.sensitivity == null ? '' : Number(camera.sensitivity),
        onvif_endpoint: camera.onvif_endpoint || '',
        onvif_username: camera.onvif_username || '',
        onvif_password: camera.onvif_password || '',
      };
    });
    setCameraRows(nextRows);
  }, [cameras]);

  useEffect(() => {
    let cancelled = false;

    const load = async () => {
      setLoading(true);
      try {
        const response = await api.getSystemSettings();
        if (cancelled) {
          return;
        }
        const data = response?.data || {};
        setSettings((prev) => ({
          ...prev,
          live_stream_mode: ['hls', 'ws', 'mjpeg', 'webrtc'].includes(data.live_stream_mode) ? data.live_stream_mode : 'mjpeg',
          clip_playback_mode: ['file', 'p2p'].includes(normalizeClipPlaybackMode(data.clip_playback_mode))
            ? normalizeClipPlaybackMode(data.clip_playback_mode)
            : 'file',
          enable_yolox: data.enable_yolox == null ? prev.enable_yolox : Boolean(data.enable_yolox),
          enable_pann: data.enable_pann == null ? prev.enable_pann : Boolean(data.enable_pann),
          max_stk_amp: Number(data.scene_analysis_config?.max_stk_amp ?? prev.max_stk_amp),
          max_osc_count: Number(data.scene_analysis_config?.max_osc_count ?? prev.max_osc_count),
          waiting_duration_threshold: Number(data.scene_analysis_config?.waiting_duration_threshold ?? prev.waiting_duration_threshold),
          waiting_zone_threshold: Number(data.scene_analysis_config?.waiting_zone_threshold ?? prev.waiting_zone_threshold),
        }));
      } catch (error) {
        toast.error(`Failed to load system settings: ${error?.response?.data?.detail || error.message}`);
      } finally {
        if (!cancelled) {
          setLoading(false);
        }
      }
    };

    load();
    return () => {
      cancelled = true;
    };
  }, []);

  const handleSaveSystemSettings = async () => {
    setSaving(true);
    try {
      const payload = {
        live_stream_mode: settings.live_stream_mode,
        clip_playback_mode: settings.clip_playback_mode,
        enable_yolox: Boolean(settings.enable_yolox),
        enable_pann: Boolean(settings.enable_pann),
        max_stk_amp: Number(settings.max_stk_amp),
        max_osc_count: Number(settings.max_osc_count),
        waiting_duration_threshold: Number(settings.waiting_duration_threshold),
        waiting_zone_threshold: Number(settings.waiting_zone_threshold),
      };
      const response = await api.updateSystemSettings(payload);
      const data = response?.data || {};
      setSettings((prev) => ({
        ...prev,
        live_stream_mode: ['hls', 'ws', 'mjpeg', 'webrtc'].includes(data.live_stream_mode) ? data.live_stream_mode : 'mjpeg',
        clip_playback_mode: ['file', 'p2p'].includes(normalizeClipPlaybackMode(data.clip_playback_mode))
          ? normalizeClipPlaybackMode(data.clip_playback_mode)
          : 'file',
        enable_yolox: data.enable_yolox == null ? prev.enable_yolox : Boolean(data.enable_yolox),
        enable_pann: data.enable_pann == null ? prev.enable_pann : Boolean(data.enable_pann),
        max_stk_amp: Number(data.scene_analysis_config?.max_stk_amp ?? prev.max_stk_amp),
        max_osc_count: Number(data.scene_analysis_config?.max_osc_count ?? prev.max_osc_count),
        waiting_duration_threshold: Number(data.scene_analysis_config?.waiting_duration_threshold ?? prev.waiting_duration_threshold),
        waiting_zone_threshold: Number(data.scene_analysis_config?.waiting_zone_threshold ?? prev.waiting_zone_threshold),
      }));
      onSettingsUpdated?.(data);
      return data;
    } catch (error) {
      toast.error(`Failed to update system settings: ${error?.response?.data?.detail || error.message}`);
      return null;
    } finally {
      setSaving(false);
    }
  };

  const handleCameraRowChange = (cameraId, key, value) => {
    setCameraRows((prev) => ({
      ...prev,
      [cameraId]: {
        ...(prev[cameraId] || {}),
        [key]: value,
      },
    }));
  };

  const handleSaveCameraRow = async (cameraId) => {
    const row = cameraRows[cameraId];
    if (!row) return;

    setSavingCameraId(cameraId);
    try {
      const payload = {
        name: String(row.name || '').trim(),
        camera_type: row.camera_type || 'rtsp',
        source: String(row.source || '').trim(),
        resolution: row.resolution || '1920x1080',
        fps: Number(row.fps) || 30,
        audio_enabled: Boolean(row.audio_enabled),
        keep_online: Boolean(row.keep_online),
        max_recordings: Math.max(1, Number(row.max_recordings) || 3000),
        sensitivity: row.sensitivity === '' || row.sensitivity == null
          ? null
          : Number(row.sensitivity),
        onvif_endpoint: String(row.onvif_endpoint || '').trim() || null,
        onvif_username: String(row.onvif_username || '').trim() || null,
        onvif_password: String(row.onvif_password || '').trim() || null,
      };

      const response = await api.updateCamera(cameraId, payload);
      if (response?.data && typeof setCameras === 'function') {
        setCameras((prev) => prev.map((camera) => (camera.id === cameraId ? response.data : camera)));
      }
      toast.success(`Updated camera ${row.name || cameraId}`);
    } catch (error) {
      toast.error(`Failed to update camera: ${error?.response?.data?.detail || error.message}`);
    } finally {
      setSavingCameraId('');
    }
  };

  const handleDeleteCamera = async (cameraId) => {
    const cameraName = cameras.find((camera) => camera.id === cameraId)?.name || cameraId;
    if (!window.confirm(`Delete camera ${cameraName}?`)) {
      return;
    }
    if (!window.confirm(`Final confirmation: this permanently deletes ${cameraName}. Continue?`)) {
      return;
    }

    setDeletingCameraId(cameraId);
    try {
      await api.deleteCamera(cameraId);
      if (typeof setCameras === 'function') {
        setCameras((prev) => prev.filter((camera) => camera.id !== cameraId));
      }
      toast.success(`Deleted camera ${cameraName}`);
    } catch (error) {
      toast.error(`Failed to delete camera: ${error?.response?.data?.detail || error.message}`);
    } finally {
      setDeletingCameraId('');
    }
  };

  const handleApplyCameraRow = async (cameraId) => {
    const row = cameraRows[cameraId];
    if (!row) return;

    setApplyingCameraId(cameraId);
    try {
      // 1. Save updated settings
      const payload = {
        name: String(row.name || '').trim(),
        camera_type: row.camera_type || 'rtsp',
        source: String(row.source || '').trim(),
        resolution: row.resolution || '1920x1080',
        fps: Number(row.fps) || 30,
        audio_enabled: Boolean(row.audio_enabled),
        keep_online: Boolean(row.keep_online),
        max_recordings: Math.max(1, Number(row.max_recordings) || 3000),
        sensitivity: row.sensitivity === '' || row.sensitivity == null
          ? null
          : Number(row.sensitivity),
        onvif_endpoint: String(row.onvif_endpoint || '').trim() || null,
        onvif_username: String(row.onvif_username || '').trim() || null,
        onvif_password: String(row.onvif_password || '').trim() || null,
      };
      const saveResp = await api.updateCamera(cameraId, payload);
      if (saveResp?.data && typeof setCameras === 'function') {
        setCameras((prev) => prev.map((camera) => (camera.id === cameraId ? saveResp.data : camera)));
      }

      // 2. Stop the camera (ignore errors if already stopped)
      try { await api.stopCamera(cameraId); } catch {}

      // 3. Start the camera again
      await api.startCamera(cameraId);
      if (typeof setCameras === 'function') {
        setCameras((prev) => prev.map((camera) =>
          camera.id === cameraId ? { ...camera, status: 'online' } : camera
        ));
      }

      toast.success(`Applied settings and restarted ${row.name || cameraId}`);
    } catch (error) {
      toast.error(`Failed to apply camera settings: ${error?.response?.data?.detail || error.message}`);
    } finally {
      setApplyingCameraId('');
    }
  };

  const handleAddCamera = async (cameraForm) => {
    try {
      const response = await api.createCamera(cameraForm);
      if (response?.data && typeof setCameras === 'function') {
        setCameras((prev) => [...prev, response.data]);
      }
      setShowAddCameraModal(false);
      setNewCamera({ ...DEFAULT_CAMERA_FORM });
      toast.success('Camera added successfully');
    } catch (error) {
      toast.error(`Failed to add camera: ${error?.response?.data?.detail || error.message}`);
    }
  };

  return (
    <div>
      <div className="page-header">
        <h1 className="page-title">System Settings</h1>
        <p className="page-subtitle">Camera settings, media modes, and AI controls</p>
      </div>

      <div className="content-section">
        <div className="section-header">
          <h2 className="section-title" style={{ color: '#004d40' }}>Camera Settings</h2>
          <button
            type="button"
            className="btn btn-primary"
            onClick={() => setShowAddCameraModal(true)}
          >
            <Plus size={16} />
            Add Camera
          </button>
        </div>

        <div className="info-card">
          {cameras.length === 0 ? (
            <div style={{ color: '#546e7a', fontWeight: 600 }}>
              No cameras configured yet. Use Add Camera to create your first camera.
            </div>
          ) : (
            <div className="camera-settings-table-wrap">
              <table className="camera-settings-table">
                <thead>
                  <tr>
                    <th>Name</th>
                    <th>Type</th>
                    <th>Source</th>
                    <th>ONVIF Endpoint</th>
                    <th>ONVIF User</th>
                    <th>ONVIF Pass</th>
                    <th>Resolution</th>
                    <th>FPS</th>
                    <th>Audio</th>
                    <th>Always On</th>
                    <th>Max Recs</th>
                    <th>Sensitivity</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {cameras.map((camera) => {
                    const row = cameraRows[camera.id] || {};
                    return (
                      <tr key={camera.id}>
                        <td>
                          <input
                            className="camera-settings-input"
                            value={row.name || ''}
                            onChange={(e) => handleCameraRowChange(camera.id, 'name', e.target.value)}
                          />
                        </td>
                        <td>
                          <select
                            className="camera-settings-input"
                            value={row.camera_type || 'rtsp'}
                            onChange={(e) => handleCameraRowChange(camera.id, 'camera_type', e.target.value)}
                          >
                            <option value="rtsp">RTSP</option>
                            <option value="webcam">Webcam</option>
                            <option value="ip_camera">IP Camera</option>
                          </select>
                        </td>
                        <td>
                          <input
                            className="camera-settings-input camera-settings-source"
                            value={row.source || ''}
                            onChange={(e) => handleCameraRowChange(camera.id, 'source', e.target.value)}
                          />
                        </td>
                        <td>
                          <input
                            className="camera-settings-input camera-settings-source"
                            value={row.onvif_endpoint || ''}
                            placeholder="192.168.1.10:80"
                            onChange={(e) => handleCameraRowChange(camera.id, 'onvif_endpoint', e.target.value)}
                          />
                        </td>
                        <td>
                          <input
                            className="camera-settings-input"
                            value={row.onvif_username || ''}
                            onChange={(e) => handleCameraRowChange(camera.id, 'onvif_username', e.target.value)}
                          />
                        </td>
                        <td>
                          <input
                            type="password"
                            className="camera-settings-input"
                            value={row.onvif_password || ''}
                            onChange={(e) => handleCameraRowChange(camera.id, 'onvif_password', e.target.value)}
                          />
                        </td>
                        <td>
                          <select
                            className="camera-settings-input"
                            value={row.resolution || '1920x1080'}
                            onChange={(e) => handleCameraRowChange(camera.id, 'resolution', e.target.value)}
                          >
                            {RESOLUTION_OPTIONS.map((option) => (
                              <option key={option.value} value={option.value}>{option.value}</option>
                            ))}
                          </select>
                        </td>
                        <td>
                          <select
                            className="camera-settings-input"
                            value={Number(row.fps) || 30}
                            onChange={(e) => handleCameraRowChange(camera.id, 'fps', Number(e.target.value))}
                          >
                            {FPS_OPTIONS.map((value) => (
                              <option key={value} value={value}>{value}</option>
                            ))}
                          </select>
                        </td>
                        <td>
                          <label className="camera-settings-toggle">
                            <input
                              type="checkbox"
                              checked={Boolean(row.audio_enabled)}
                              onChange={(e) => handleCameraRowChange(camera.id, 'audio_enabled', e.target.checked)}
                            />
                            <span>{row.audio_enabled ? 'On' : 'Off'}</span>
                          </label>
                        </td>
                        <td>
                          <label className="camera-settings-toggle">
                            <input
                              type="checkbox"
                              checked={Boolean(row.keep_online)}
                              onChange={(e) => handleCameraRowChange(camera.id, 'keep_online', e.target.checked)}
                            />
                            <span>{row.keep_online ? 'On' : 'Off'}</span>
                          </label>
                        </td>
                        <td>
                          <input
                            type="number"
                            className="camera-settings-input camera-settings-small"
                            min="1"
                            step="1"
                            value={Number(row.max_recordings) || 3000}
                            onChange={(e) => handleCameraRowChange(camera.id, 'max_recordings', Number(e.target.value))}
                          />
                        </td>
                        <td>
                          <select
                            className="camera-settings-input camera-settings-small"
                            value={row.sensitivity ?? ''}
                            onChange={(e) => handleCameraRowChange(
                              camera.id,
                              'sensitivity',
                              e.target.value === '' ? '' : Number(e.target.value),
                            )}
                            title="Higher sensitivity uses a shorter minimum trajectory"
                          >
                            <option value="">System</option>
                            {[7, 6, 5, 4, 3, 2, 1].map((value) => (
                              <option key={value} value={value}>{value}</option>
                            ))}
                          </select>
                        </td>
                        <td>
                          <div className="camera-settings-actions">
                            <button
                              type="button"
                              className="btn btn-primary"
                              style={{ padding: '5px 8px', fontSize: '11px', lineHeight: 1 }}
                              disabled={savingCameraId === camera.id || applyingCameraId === camera.id}
                              onClick={() => handleSaveCameraRow(camera.id)}
                            >
                              <Save size={14} />
                              {savingCameraId === camera.id ? 'Saving...' : 'Save'}
                            </button>
                            <button
                              type="button"
                              className="btn btn-secondary"
                              style={{ padding: '5px 8px', fontSize: '11px', lineHeight: 1 }}
                              disabled={applyingCameraId === camera.id || savingCameraId === camera.id}
                              onClick={() => handleApplyCameraRow(camera.id)}
                              title="Save settings then stop & restart camera"
                            >
                              <RefreshCw
                                size={14}
                                style={{ animation: applyingCameraId === camera.id ? 'btn-spin 1s linear infinite' : 'none' }}
                              />
                              {applyingCameraId === camera.id ? 'Applying...' : 'Apply'}
                            </button>
                            <button
                              type="button"
                              className="btn btn-danger"
                              style={{ padding: '5px 8px', fontSize: '11px', lineHeight: 1 }}
                              disabled={deletingCameraId === camera.id}
                              onClick={() => handleDeleteCamera(camera.id)}
                            >
                              <Trash2 size={14} />
                              {deletingCameraId === camera.id ? 'Deleting...' : 'Delete'}
                            </button>
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>

      <div className="system-info-grid system-settings-grid settings-compact-controls">
        <div className="info-card">
          <h3 className="info-title">Media</h3>

          <div className="info-item" style={{ alignItems: 'center' }}>
            <span className="info-label">Camera streaming mode</span>
            <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', justifyContent: 'flex-end' }}>
              {[
                ['webrtc', 'WR'],
                ['ws', 'WS'],
                ['hls', 'HS'],
                ['mjpeg', 'MG'],
              ].map(([mode, label]) => (
                <button
                  key={mode}
                  type="button"
                  className={settings.live_stream_mode === mode ? 'btn btn-primary' : 'btn btn-secondary'}
                  onClick={() => setSettings((prev) => ({ ...prev, live_stream_mode: mode }))}
                >
                  {label}
                </button>
              ))}
            </div>
          </div>

          <div className="info-item" style={{ alignItems: 'center' }}>
            <span className="info-label">Playback</span>
            <div style={{ display: 'flex', gap: 8 }}>
              <button
                type="button"
                className={settings.clip_playback_mode === 'file' ? 'btn btn-primary' : 'btn btn-secondary'}
                onClick={() => setSettings((prev) => ({ ...prev, clip_playback_mode: 'file' }))}
              >
                FL
              </button>
              <button
                type="button"
                className={settings.clip_playback_mode === 'p2p' ? 'btn btn-primary' : 'btn btn-secondary'}
                onClick={() => setSettings((prev) => ({ ...prev, clip_playback_mode: 'p2p' }))}
              >
                P2P
              </button>
            </div>
          </div>
        </div>

        <div className="info-card">
          <h3 className="info-title">AI</h3>

          <div className="info-item" style={{ alignItems: 'center' }}>
            <span className="info-label">Enable Video Det</span>
            <label className="camera-settings-toggle">
              <input
                type="checkbox"
                checked={Boolean(settings.enable_yolox)}
                onChange={(e) => setSettings((prev) => ({ ...prev, enable_yolox: e.target.checked }))}
              />
              <span>{settings.enable_yolox ? 'On' : 'Off'}</span>
            </label>
          </div>

          <div className="info-item" style={{ alignItems: 'center' }}>
            <span className="info-label">Enable Audio Det</span>
            <label className="camera-settings-toggle">
              <input
                type="checkbox"
                checked={Boolean(settings.enable_pann)}
                onChange={(e) => setSettings((prev) => ({ ...prev, enable_pann: e.target.checked }))}
              />
              <span>{settings.enable_pann ? 'On' : 'Off'}</span>
            </label>
          </div>
        </div>

        <div className="info-card">
          <h3 className="info-title">AI Parameters</h3>

          <div className="info-item" style={PARAM_ROW_STYLE}>
            <span className="info-label" style={PARAM_LABEL_STYLE}>Max Stk Amp</span>
            <div style={PARAM_CONTROL_STYLE}>
              <input
                type="number"
                min="0"
                step="0.1"
                value={settings.max_stk_amp}
                onChange={(e) => setSettings((prev) => ({ ...prev, max_stk_amp: Number(e.target.value || 0) }))}
                style={PARAM_INPUT_STYLE}
              />
              <span className="info-value" style={PARAM_UNIT_STYLE}> </span>
            </div>
          </div>

          <div className="info-item" style={PARAM_ROW_STYLE}>
            <span className="info-label" style={PARAM_LABEL_STYLE}>Max Osc Count</span>
            <div style={PARAM_CONTROL_STYLE}>
              <input
                type="number"
                min="1"
                step="1"
                value={settings.max_osc_count}
                onChange={(e) => setSettings((prev) => ({ ...prev, max_osc_count: Number(e.target.value || 1) }))}
                style={PARAM_INPUT_STYLE}
              />
              <span className="info-value" style={PARAM_UNIT_STYLE}> </span>
            </div>
          </div>

          <div className="info-item" style={PARAM_ROW_STYLE}>
            <span className="info-label" style={PARAM_LABEL_STYLE}>Waiting Duration Thr</span>
            <div style={PARAM_CONTROL_STYLE}>
              <input
                type="number"
                min="0"
                step="1"
                value={settings.waiting_duration_threshold}
                onChange={(e) => setSettings((prev) => ({ ...prev, waiting_duration_threshold: Number(e.target.value || 0) }))}
                style={PARAM_INPUT_STYLE}
              />
              <span className="info-value" style={PARAM_UNIT_STYLE}>sec</span>
            </div>
          </div>

          <div className="info-item" style={PARAM_ROW_STYLE}>
            <span className="info-label" style={PARAM_LABEL_STYLE}>Waiting Zone Thr</span>
            <div style={PARAM_CONTROL_STYLE}>
              <input
                type="number"
                min="0"
                step="0.01"
                value={settings.waiting_zone_threshold}
                onChange={(e) => setSettings((prev) => ({ ...prev, waiting_zone_threshold: Number(e.target.value || 0) }))}
                style={PARAM_INPUT_STYLE}
              />
              <span className="info-value" style={PARAM_UNIT_STYLE}> </span>
            </div>
          </div>
        </div>
      </div>

      {/* Save System Settings Button */}
      <div style={{ marginTop: 16, display: 'flex', justifyContent: 'flex-end' }}>
        <button type="button" className="btn btn-primary settings-save-btn" disabled={saving || loading} onClick={async () => {
          const data = await handleSaveSystemSettings();
          if (data) toast.success('System settings saved');
        }}>
          {saving ? 'Saving...' : 'Save System Settings'}
        </button>
      </div>

      {showAddCameraModal && (
        <CameraForm
          key="settings-add-camera"
          initialCamera={newCamera}
          onSubmit={handleAddCamera}
          onClose={() => setShowAddCameraModal(false)}
          title="Add New Camera"
          submitText="Add Camera"
        />
      )}
    </div>
  );
};

export default SystemSettings;
