const REQUEST_TIMEOUT_MS = 30000;
const PREPARATION_TIMEOUT_MS = 10 * 60 * 1000;

const randomId = () => (
  window.crypto?.randomUUID?.()
  || `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`
);

const protocolError = (message, code = 'CLIP_PROTOCOL_ERROR') => {
  const error = new Error(message);
  error.code = code;
  return error;
};

/** Match JSON responses and ordered binary transfers by requestId. */
export class ClipProtocolClient {
  constructor(controlChannel, mediaChannel) {
    this.control = controlChannel;
    this.media = mediaChannel;
    this.pending = new Map();
    this.activeTransfer = null;
    this.closed = false;
    this.media.binaryType = 'arraybuffer';
    this.control.onmessage = (event) => this.handleControl(event.data);
    this.media.onmessage = (event) => this.handleMedia(event.data);
  }

  requestMetadata(clipId) {
    return this.requestJson('get_metadata', { clipId }, PREPARATION_TIMEOUT_MS);
  }

  requestInit(clipId) {
    return this.requestBinary('get_init', { clipId });
  }

  requestFragment(clipId, fragmentIndex) {
    return this.requestBinary('get_fragment', { clipId, fragmentIndex });
  }

  createPending(requestId, expectedType, operation, timeoutMs = REQUEST_TIMEOUT_MS) {
    let resolve;
    let reject;
    const promise = new Promise((resolvePromise, rejectPromise) => {
      resolve = resolvePromise;
      reject = rejectPromise;
    });
    const timer = window.setTimeout(() => {
      this.pending.delete(requestId);
      const transfer = this.activeTransfer;
      let progress = '';
      if (expectedType === 'binary') {
        if (String(transfer?.header?.requestId || '') === requestId) {
          const totalChunks = Number(transfer.header.chunkCount) || 0;
          const receivedChunks = totalChunks - transfer.remaining;
          progress = `: received ${receivedChunks}/${totalChunks} chunks, `
            + `${transfer.receivedBytes}/${Number(transfer.header.totalBytes) || 0} bytes`;
        } else {
          progress = ': no media header received';
        }
      }
      reject(protocolError(`${operation} timed out${progress}`, 'CLIP_REQUEST_TIMEOUT'));
    }, timeoutMs);
    this.pending.set(requestId, {
      requestId, expectedType, operation, resolve, reject, timer,
    });
    return { requestId, promise };
  }

  requestJson(type, payload, timeoutMs = REQUEST_TIMEOUT_MS) {
    const requestId = randomId();
    const request = this.createPending(requestId, 'metadata', type, timeoutMs);
    this.send({ type, requestId, ...payload });
    return request;
  }

  requestBinary(type, payload) {
    const requestId = randomId();
    const operation = type === 'get_fragment'
      ? `${type} fragment=${payload.fragmentIndex}`
      : type;
    const request = this.createPending(requestId, 'binary', operation);
    this.send({ type, requestId, ...payload });
    return request;
  }

  send(message) {
    if (this.closed || this.control.readyState !== 'open') {
      throw protocolError('Clip control channel is closed', 'CLIP_CHANNEL_CLOSED');
    }
    this.control.send(JSON.stringify(message));
  }

  cancel(requestIds) {
    const activeIds = requestIds.filter(Boolean).map(String);
    if (!activeIds.length) return;
    activeIds.forEach((requestId) => {
      const request = this.pending.get(requestId);
      if (!request) return;
      window.clearTimeout(request.timer);
      this.pending.delete(requestId);
      request.reject(protocolError('Clip request cancelled', 'CLIP_REQUEST_CANCELLED'));
    });
    if (this.activeTransfer
        && activeIds.includes(String(this.activeTransfer.header?.requestId || ''))) {
      this.activeTransfer.chunks = [];
      this.activeTransfer.ignored = true;
    }
    if (this.control.readyState === 'open') {
      this.control.send(JSON.stringify({ type: 'cancel', requestIds: activeIds }));
    }
  }

  handleControl(raw) {
    if (typeof raw !== 'string') return;
    let message;
    try {
      message = JSON.parse(raw);
    } catch (_error) {
      return;
    }
    if (message.type === 'revoked') {
      this.failAll(protocolError(message.message, message.code));
      return;
    }
    if (message.type === 'binary_header') {
      this.beginTransfer(message);
      return;
    }
    const request = this.pending.get(String(message.requestId || ''));
    if (!request) return;
    if (message.type === 'error') {
      this.settleError(request, protocolError(message.message, message.code));
    } else if (message.type === 'metadata' && request.expectedType === 'metadata') {
      this.settleSuccess(request, message.metadata);
    }
  }

  beginTransfer(header) {
    const request = this.pending.get(String(header.requestId || ''));
    if (!request || request.expectedType !== 'binary') {
      this.activeTransfer = { ignored: true, remaining: Number(header.chunkCount) || 0 };
      return;
    }
    this.activeTransfer = {
      request,
      header,
      chunks: [],
      receivedBytes: 0,
      remaining: Number(header.chunkCount) || 0,
    };
    this.send({ type: 'binary_ready', requestId: request.requestId });
    if (this.activeTransfer.remaining === 0) this.finishTransfer();
  }

  handleMedia(raw) {
    if (typeof raw === 'string') return;
    const transfer = this.activeTransfer;
    if (!transfer) return;
    if (transfer.ignored) {
      transfer.remaining -= 1;
      if (transfer.remaining <= 0) this.activeTransfer = null;
      return;
    }
    const chunk = raw instanceof ArrayBuffer ? new Uint8Array(raw) : new Uint8Array(raw);
    transfer.chunks.push(chunk);
    transfer.receivedBytes += chunk.byteLength;
    transfer.remaining -= 1;
    if (transfer.remaining <= 0) this.finishTransfer();
  }

  finishTransfer() {
    const transfer = this.activeTransfer;
    this.activeTransfer = null;
    if (!transfer || transfer.ignored) return;
    if (transfer.receivedBytes !== Number(transfer.header.totalBytes)) {
      this.settleError(transfer.request, protocolError(
        `Incomplete clip transfer (${transfer.receivedBytes}/${transfer.header.totalBytes} bytes)`,
        'INCOMPLETE_TRANSFER',
      ));
      return;
    }
    const data = new Uint8Array(transfer.receivedBytes);
    let offset = 0;
    transfer.chunks.forEach((chunk) => {
      data.set(chunk, offset);
      offset += chunk.byteLength;
    });
    this.settleSuccess(transfer.request, { header: transfer.header, data });
  }

  settleSuccess(request, value) {
    window.clearTimeout(request.timer);
    this.pending.delete(request.requestId);
    request.resolve(value);
  }

  settleError(request, error) {
    window.clearTimeout(request.timer);
    this.pending.delete(request.requestId);
    request.reject(error);
  }

  failAll(error) {
    this.pending.forEach((request) => {
      window.clearTimeout(request.timer);
      request.reject(error);
    });
    this.pending.clear();
  }

  close() {
    if (this.closed) return;
    this.closed = true;
    this.failAll(protocolError('Clip protocol closed', 'CLIP_SESSION_CLOSED'));
    this.activeTransfer = null;
  }
}

/** Present the HTTP fMP4 endpoints through the interface consumed by MseClipPlayer. */
export class HttpClipProtocolClient {
  constructor(httpApi) {
    this.httpApi = httpApi;
    this.pending = new Map();
    this.closed = false;
  }

  request(operation, loader) {
    const requestId = randomId();
    if (this.closed) {
      return {
        requestId,
        promise: Promise.reject(protocolError('Clip protocol closed', 'CLIP_SESSION_CLOSED')),
      };
    }
    const controller = new AbortController();
    const promise = loader(controller.signal)
      .catch((error) => {
        if (controller.signal.aborted) {
          throw protocolError('Clip request cancelled', 'CLIP_REQUEST_CANCELLED');
        }
        throw error;
      })
      .finally(() => this.pending.delete(requestId));
    this.pending.set(requestId, { operation, controller });
    return { requestId, promise };
  }

  requestMetadata(clipId) {
    return this.request('get_metadata', async (signal) => {
      const response = await this.httpApi.getClipMseMetadata(clipId, signal);
      return response.data;
    });
  }

  requestInit(clipId) {
    return this.request('get_init', async (signal) => {
      const response = await this.httpApi.getClipMseInit(clipId, signal);
      return { data: new Uint8Array(response.data) };
    });
  }

  requestFragment(clipId, fragmentIndex) {
    return this.request(`get_fragment fragment=${fragmentIndex}`, async (signal) => {
      const response = await this.httpApi.getClipMseFragment(clipId, fragmentIndex, signal);
      return { data: new Uint8Array(response.data) };
    });
  }

  cancel(requestIds) {
    requestIds.map(String).forEach((requestId) => {
      this.pending.get(requestId)?.controller.abort();
    });
  }

  close() {
    if (this.closed) return;
    this.closed = true;
    this.pending.forEach(({ controller }) => controller.abort());
    this.pending.clear();
  }
}

export { protocolError };
