import { transportApi } from './api';
import { buildIceServers, waitForIceGathering } from './webrtc';
import { ClipProtocolClient, protocolError } from './clip_protocol';
import { MseClipPlayer } from './mse_clip_player';

const CHANNEL_OPEN_TIMEOUT_MS = 30000;

const channelOpen = (channel) => new Promise((resolve, reject) => {
  if (channel.readyState === 'open') {
    resolve();
    return;
  }
  const cleanup = () => {
    window.clearTimeout(timer);
    channel.removeEventListener('open', onOpen);
    channel.removeEventListener('error', onError);
    channel.removeEventListener('close', onClose);
  };
  const onOpen = () => {
    cleanup();
    resolve();
  };
  const onError = () => {
    cleanup();
    reject(protocolError(`${channel.label} DataChannel failed`, 'CLIP_CHANNEL_FAILED'));
  };
  const onClose = () => {
    cleanup();
    reject(protocolError(`${channel.label} DataChannel closed`, 'CLIP_CHANNEL_CLOSED'));
  };
  const timer = window.setTimeout(() => {
    cleanup();
    reject(protocolError(`${channel.label} DataChannel timed out`, 'CLIP_CHANNEL_TIMEOUT'));
  }, CHANNEL_OPEN_TIMEOUT_MS);
  channel.addEventListener('open', onOpen);
  channel.addEventListener('error', onError);
  channel.addEventListener('close', onClose);
});

/** One persistent peer; each play attaches a fresh MediaSource to the selected video. */
export const createPersistentClipChannel = ({ onState } = {}) => {
  let peer = null;
  let control = null;
  let media = null;
  let protocol = null;
  let player = null;
  let sessionId = null;
  let closed = false;

  const notify = (state, detail = {}) => onState?.({ state, ...detail });
  let resolveReady;
  let rejectReady;
  const ready = new Promise((resolve, reject) => {
    resolveReady = resolve;
    rejectReady = reject;
  });

  const detach = (element) => {
    if (player && (!element || player.video === element)) {
      player.destroy();
      player = null;
    }
  };

  const close = () => {
    if (closed) return;
    closed = true;
    rejectReady(protocolError('Clip session is closed', 'CLIP_SESSION_CLOSED'));
    detach();
    protocol?.close();
    if (control && control.readyState !== 'closed') control.close();
    if (media && media.readyState !== 'closed') media.close();
    peer?.close();
    if (sessionId) transportApi.stopPersistentClipWebRtc(sessionId).catch(() => {});
    notify('closed');
  };

  const connect = async () => {
    try {
      notify('connecting');
      const config = await transportApi.getIceConfig();
      peer = new RTCPeerConnection({
        iceServers: buildIceServers(config),
        iceTransportPolicy: 'all',
      });
      control = peer.createDataChannel('control', { ordered: true });
      media = peer.createDataChannel('media', { ordered: true });
      const channelsReady = Promise.all([channelOpen(control), channelOpen(media)]);

      peer.onconnectionstatechange = () => {
        if (closed || !['failed', 'disconnected'].includes(peer.connectionState)) return;
        const error = protocolError(`Clip WebRTC ${peer.connectionState}`, 'CLIP_CONNECTION_FAILED');
        protocol?.failAll(error);
        notify('failed', { error });
      };

      const offer = await peer.createOffer();
      await peer.setLocalDescription(offer);
      await waitForIceGathering(peer);
      const response = await transportApi.startPersistentClipWebRtc(
        peer.localDescription.sdp,
      );
      sessionId = response.session_id;
      if (closed) {
        transportApi.stopPersistentClipWebRtc(sessionId).catch(() => {});
        return;
      }
      await peer.setRemoteDescription({ type: 'answer', sdp: response.sdp });
      await channelsReady;
      protocol = new ClipProtocolClient(control, media);
      resolveReady();
      notify('ready', { sessionId });
    } catch (error) {
      rejectReady(error);
      notify('failed', { error });
      close();
    }
  };

  const play = async ({ recordingId, videoElement }) => {
    await ready;
    if (closed) throw protocolError('Clip session is closed', 'CLIP_SESSION_CLOSED');
    detach();
    const nextPlayer = new MseClipPlayer({
      protocol,
      clipId: recordingId,
      videoElement,
      onState: ({ state, ...detail }) => notify(state, detail),
    });
    player = nextPlayer;
    try {
      await nextPlayer.start();
    } catch (error) {
      // A newer play() intentionally destroys the prior player and cancels its
      // requests; that obsolete call must not trigger HTTP fallback in its card.
      if (player !== nextPlayer) return;
      if (player?.video === videoElement) {
        nextPlayer.destroy();
        player = null;
      }
      throw error;
    }
  };

  const stop = () => detach();

  connect();
  return { ready, play, stop, detach, close };
};
