import axios from 'axios';
import { getApiBaseUrl, LOCAL_API_BASE_URL } from './connection';

// Frontend HTTP request timeouts. Keep these values together so timeout
// behavior is visible and can be adjusted without searching individual calls.
export const API_TIMEOUT_MS = Object.freeze({
  DEFAULT: 10000,
  LOGIN: 60000,
  INITIAL_DATA: 60000,
  CAMERA_OPERATION: 60000,
  RECORDING_OPERATION: 60000,
  WIFI_SCAN: 60000,
  ONVIF_DISCOVERY: 60000,
  PERSON_SEARCH: 60000,
  WEBRTC_TRANSPORT: 60000,
});

export {
  API_ENDPOINT_MODES,
  LOCAL_API_BASE_URL,
  REMOTE_API_BASE_URL,
  getCurrentApiBaseUrl,
  normalizeApiBaseUrl,
  getApiEndpointMode,
  getCustomApiBaseUrl,
  getLocalDeviceId,
  getLocalApiBaseUrl,
  normalizeLocalDeviceId,
  setDiscoveredApiEndpoints,
  getApiBaseUrlForMode,
  getApiBaseUrl,
  setApiEndpointMode,
  setCustomApiBaseUrl,
  setLocalDeviceId,
  getApiEndpointSettings,
} from './connection';

const TOKEN_STORAGE_KEY = 'nvr_access_token';
const RECORDING_PLAYBACK_MODE_KEY = 'nvr_recording_playback_mode';

const normalizePlaybackModeStorage = (mode) => (
  ['file', 'p2p'].includes(mode) ? mode : 'file'
);

const clearRecordingCaches = () => {
  if (typeof navigator !== 'undefined' && navigator.serviceWorker?.controller) {
    navigator.serviceWorker.controller.postMessage({ type: 'NVR_CLEAR_RECORDING_CACHES' });
  }
};

export const getStoredToken = () => (
  localStorage.getItem(TOKEN_STORAGE_KEY)
  || sessionStorage.getItem(TOKEN_STORAGE_KEY)
);

const getStoredRecordingPlaybackMode = () =>
  normalizePlaybackModeStorage(localStorage.getItem(RECORDING_PLAYBACK_MODE_KEY));

const buildUrlWithToken = (path) => {
  const token = getStoredToken();
  const base = `${getApiBaseUrl()}${path}`;
  if (!token) {
    return base;
  }
  const separator = base.includes('?') ? '&' : '?';
  return `${base}${separator}access_token=${encodeURIComponent(token)}`;
};

const appendQueryParams = (url, params = {}) => {
  const entries = Object.entries(params).filter(([, value]) => value !== undefined && value !== null && value !== '');
  if (entries.length === 0) {
    return url;
  }
  const separator = url.includes('?') ? '&' : '?';
  const query = entries
    .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(String(value))}`)
    .join('&');
  return `${url}${separator}${query}`;
};

export const apiClient = axios.create({
  baseURL: `${LOCAL_API_BASE_URL}/api`,
  timeout: API_TIMEOUT_MS.DEFAULT,
});

apiClient.interceptors.request.use((config) => {
  config.baseURL = `${getApiBaseUrl()}/api`;
  const token = getStoredToken();
  if (token) {
    config.headers = config.headers || {};
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
}, (error) => Promise.reject(error));

export const api = {
  // Auth endpoints
  login: (password) => apiClient.post(
    '/auth/login',
    { password },
    { timeout: API_TIMEOUT_MS.LOGIN },
  ),
  changePassword: (currentPassword, newPassword) => apiClient.put('/auth/password', {
    current_password: currentPassword,
    new_password: newPassword,
  }),
  setAccessToken: (token, stayLoggedIn) => {
    const previousToken = getStoredToken();
    const persistent = stayLoggedIn === undefined
      ? Boolean(localStorage.getItem(TOKEN_STORAGE_KEY))
        || !sessionStorage.getItem(TOKEN_STORAGE_KEY)
      : Boolean(stayLoggedIn);
    localStorage.removeItem(TOKEN_STORAGE_KEY);
    sessionStorage.removeItem(TOKEN_STORAGE_KEY);
    if (token) {
      const storage = persistent ? localStorage : sessionStorage;
      storage.setItem(TOKEN_STORAGE_KEY, token);
    }
    if (token !== previousToken) clearRecordingCaches();
  },
  getAccessToken: () => getStoredToken(),
  clearAccessToken: () => {
    localStorage.removeItem(TOKEN_STORAGE_KEY);
    sessionStorage.removeItem(TOKEN_STORAGE_KEY);
    clearRecordingCaches();
  },
  getRecordingPlaybackMode: () => getStoredRecordingPlaybackMode(),
  setRecordingPlaybackMode: (mode) => {
    localStorage.setItem(RECORDING_PLAYBACK_MODE_KEY, normalizePlaybackModeStorage(mode));
  },
  getLiveStreamMode: async () => {
    const response = await apiClient.get('/system/live-stream-mode');
    const mode = response?.data?.live_stream_mode;
    return ['mjpeg', 'hls', 'ws', 'webrtc'].includes(mode) ? mode : 'mjpeg';
  },
  setLiveStreamMode: async (mode) => {
    const normalized = ['mjpeg', 'hls', 'ws', 'webrtc'].includes(mode) ? mode : 'mjpeg';
    const response = await apiClient.post('/system/live-stream-mode', { mode: normalized });
    const updatedMode = response?.data?.live_stream_mode;
    return ['mjpeg', 'hls', 'ws', 'webrtc'].includes(updatedMode) ? updatedMode : 'mjpeg';
  },
  appendQueryParams,

  // Camera endpoints
  getCameras: () => apiClient.get('/cameras', { timeout: API_TIMEOUT_MS.INITIAL_DATA }),
  createCamera: (camera) => apiClient.post('/cameras', camera),
  updateCamera: (cameraId, updates) => apiClient.put(`/cameras/${cameraId}`, updates),
  deleteCamera: (cameraId) => apiClient.delete(`/cameras/${cameraId}`),
  browseFiles: (path) => apiClient.get('/browse-files', { params: path ? { path } : {} }),
  startCamera: (cameraId) => apiClient.post(`/cameras/${cameraId}/start`, null, { timeout: API_TIMEOUT_MS.CAMERA_OPERATION }),
  stopCamera: (cameraId) => apiClient.post(`/cameras/${cameraId}/stop`, null, { timeout: API_TIMEOUT_MS.CAMERA_OPERATION }),
  restartCamera: (cameraId) => apiClient.post(`/cameras/${cameraId}/restart`, null, { timeout: API_TIMEOUT_MS.CAMERA_OPERATION }),
  
  // Recording endpoints
  startRecording: (cameraId) => apiClient.post(
    `/cameras/${cameraId}/start-recording`,
    null,
    { timeout: API_TIMEOUT_MS.RECORDING_OPERATION },
  ),
  stopRecording: (cameraId) => apiClient.post(`/cameras/${cameraId}/stop-recording`, null, { timeout: API_TIMEOUT_MS.RECORDING_OPERATION }),
  getRecordings: (cameraId = null) => {
    const params = cameraId ? { camera_id: cameraId } : {};
    return apiClient.get('/recordings', {
      params,
      timeout: API_TIMEOUT_MS.INITIAL_DATA,
    });
  },
  getRecordingsSummary: (cameraId = null, limit = 300, offset = 0, recordingDate = null) => {
    const params = { limit, offset };
    if (cameraId) params.camera_id = cameraId;
    if (recordingDate) params.date = recordingDate;
    return apiClient.get('/recordings/summary', {
      params,
      timeout: API_TIMEOUT_MS.INITIAL_DATA,
    });
  },
  getRecordingStorageInfo: () => apiClient.get('/recordings/storage'),
  deleteRecording: (recordingId) => apiClient.delete(`/recordings/${recordingId}`),
  updateRecordingMeta: (recordingId, data) => apiClient.patch(`/recordings/${recordingId}/meta`, data),
  downloadRecording: (recordingId) => {
    return buildUrlWithToken(`/api/recordings/${recordingId}/download`);
  },
  getMotionData: (recordingId) => apiClient.get(`/recordings/${recordingId}/motion-data`),
  
  // Streaming endpoints
  getCameraMjpegStreamUrl: (cameraId) =>
    buildUrlWithToken(`/api/cameras/${cameraId}/mjpeg`),
  getCameraHlsManifestUrl: (cameraId) => buildUrlWithToken(`/api/cameras/${cameraId}/hls/index.m3u8`),
  getCameraAudioStreamUrl: (cameraId, fmt = 'wav', nonce = null) => {
    const base = buildUrlWithToken(`/api/cameras/${cameraId}/audio_stream?fmt=${encodeURIComponent(fmt)}`);
    return nonce ? appendQueryParams(base, { nonce }) : base;
  },
  getBlankStreamUrl: (cameraId) => buildUrlWithToken(`/api/cameras/${cameraId}/stream/blank`),
  getRecordingStreamUrl: (recordingId, overlay = false) => {
    const base = buildUrlWithToken(`/api/recordings/${recordingId}/play`);
    return overlay ? appendQueryParams(base, { overlay: 'true' }) : base;
  },
  getRecordingPlaybackLimit: (recordingId) =>
    apiClient.get(`/recordings/${recordingId}/play-limit`),
  getRecordingThumbnailUrl: (recordingId, thumbnailType = 'main') => {
    const baseUrl = buildUrlWithToken(`/api/recordings/${recordingId}/thumbnail`);
    return thumbnailType !== 'main' ? appendQueryParams(baseUrl, { type: thumbnailType }) : baseUrl;
  },
  getRecordingChangeImageUrl: (recordingId, type) => buildUrlWithToken(`/api/recordings/${recordingId}/change/${type}.jpg`),
  generateOverlay: (recordingId) => apiClient.post(`/recordings/${recordingId}/overlay/generate`),
  getOverlayStatus: (recordingId) => apiClient.get(`/recordings/${recordingId}/overlay/status`),
  getProcessingStreamUrl: (cameraId) => buildUrlWithToken(`/api/cameras/${cameraId}/processing_stream`),
  getResultStreamUrl: (cameraId) => buildUrlWithToken(`/api/cameras/${cameraId}/result_stream`),
  
  // System endpoints
  getSystemInfo: (refreshNetworkEndpoints = false) => apiClient.get('/system/info', {
    params: refreshNetworkEndpoints ? { refresh_network_endpoints: true } : {},
    timeout: API_TIMEOUT_MS.INITIAL_DATA,
  }),
  getServerTimezone: async () => {
    const response = await apiClient.get('/system/info');
    return response?.data?.timezone || null;
  },
  getSystemSettings: () => apiClient.get('/system/settings'),
  updateSystemSettings: (settings) => apiClient.put('/system/settings', settings),
  getWifiStatus: () => apiClient.get('/system/wifi/status'),
  getWifiNetworks: () => apiClient.get('/system/wifi/networks', { timeout: API_TIMEOUT_MS.WIFI_SCAN }),
  connectWifi: (ssid, password = '') => apiClient.post('/system/wifi/connect', { ssid, password }),
  startWifiHotspot: () => apiClient.post('/system/wifi/hotspot'),
  
  // Preset management endpoints
  getSystemPresets: () => apiClient.get('/system/presets'),
  updatePerformanceProfile: (payload) => apiClient.put('/system/performance-profile', payload),

  getResourceHistory: () => apiClient.get('/system/resource-history'),

  // ONVIF network endpoints
  onvifDiscovery: (payload) => apiClient.post(
    '/system/network/onvif/discovery',
    payload,
    { timeout: API_TIMEOUT_MS.ONVIF_DISCOVERY },
  ),
  onvifLogin: (payload) => apiClient.post('/system/network/onvif/login', payload),
  onvifProfiles: (payload) => apiClient.post('/system/network/onvif/profiles', payload),
  onvifStreamUrl: (payload) => apiClient.post('/system/network/onvif/stream-url', payload),
  onvifCreateCamera: (payload) => apiClient.post('/system/network/onvif/create-camera', payload),
  getOnvifEvents: (cameraId, limit = 50, autostart = true) => apiClient.get('/system/network/onvif/events', {
    params: {
      camera_id: cameraId,
      limit,
      autostart,
    },
  }),

  // Archive endpoints
  exportArchive: (filters = {}) => apiClient.post('/recordings/archive/export', filters),
  listArchives: () => apiClient.get('/recordings/archive/list'),
  loadArchive: (archivePath, cameraId = null) => apiClient.post('/recordings/archive/load', {
    archive_path: archivePath,
    ...(cameraId ? { camera_id: cameraId } : {}),
  }),
  unloadArchive: (archivePath, cameraId = null) => apiClient.post('/recordings/archive/unload', {
    archive_path: archivePath,
    ...(cameraId ? { camera_id: cameraId } : {}),
  }),

  // ── Person Gallery / ReID ────────────────────────────────────────────────
  // List all person crops detected on a date or date range (YYYY-MM-DD).
  getPersonsByDate: (dateFrom, dateTo = null, cameraId = null) => {
    const params = {};
    if (dateTo && dateTo !== dateFrom) {
      params.date_from = dateFrom;
      params.date_to = dateTo;
    } else {
      params.date = dateFrom;
    }
    if (cameraId) params.camera_id = cameraId;
    return apiClient.get('/persons', { params });
  },

  // Serve a person crop image URL (with auth token baked in).
  getPersonImageUrl: (recordingId, pid) =>
    buildUrlWithToken(`/api/recordings/${encodeURIComponent(recordingId)}/persons/${pid}/image`),

  // List the person crops belonging to one recording.
  getRecordingPersons: (recordingId) =>
    apiClient.get(`/recordings/${encodeURIComponent(recordingId)}/persons`),

  // Similarity search: find clips matching a gallery-selected person.
  searchPersons: (body) => apiClient.post('/persons/search', body, { timeout: API_TIMEOUT_MS.PERSON_SEARCH }),

  // Similarity search: upload an external probe photo.
  searchPersonsByUpload: (file, { date_from, date_to, camera_id, top_k = 20, threshold = 0.55 }) => {
    const form = new FormData();
    form.append('file', file);
    const params = { date_from, date_to, top_k, threshold };
    if (camera_id) params.camera_id = camera_id;
    return apiClient.post('/persons/search/upload', form, {
      params,
      timeout: API_TIMEOUT_MS.PERSON_SEARCH,
      headers: { 'Content-Type': 'multipart/form-data' },
    });
  },

  // ReID model status (reid_enabled, model_variant).
  getReidStatus: () => apiClient.get('/persons/status'),
  // ────────────────────────────────────────────────────────────────────────
};

export default api;
