// Module-level cache: persists for the lifetime of the browser session
const MOTION_CACHE_MAX = 25;
const MOTION_PLOT_HEIGHT = 15;
const MOTION_VELOCITY_SCALE_MAX = 1.5;
const motionDataCache = {};
const motionCacheKeys = [];

export const showRecordingPlaybackLimitToast = async (recordingId) => {
  try {
    const response = await api.getRecordingPlaybackLimit(recordingId);
    if (response.data?.allowed === false && response.data?.message) {
      toast.error(response.data.message, { id: `recording-rate-limit-${recordingId}` });
    }
  } catch (_error) {
  }
};

/** Size an event clip stage to the intrinsic thumbnail or video dimensions. */
export const fitReelToMediaAspectRatio = (event) => {
  const media = event.currentTarget;
  const width = Number(media.videoWidth || media.naturalWidth);
  const height = Number(media.videoHeight || media.naturalHeight);
  const stage = media.closest?.('.reel-thumbnail');
  if (stage && width > 0 && height > 0) {
    stage.style.aspectRatio = `${width} / ${height}`;
  }
};

function cacheMotionData(recordingId, data) {
  if (motionCacheKeys.length >= MOTION_CACHE_MAX && !motionDataCache[recordingId]) {
    const oldest = motionCacheKeys.shift();
    delete motionDataCache[oldest];
  }
  motionDataCache[recordingId] = data;
  if (!motionCacheKeys.includes(recordingId)) {
    motionCacheKeys.push(recordingId);
  }
}

/**
 * Simple motion plot component for individual recordings
 * Displays velocity as a line chart below progress bar
 */
const SimpleMotionPlot = ({ recording, MOTION_COLORS }) => {
  const [motionData, setMotionData] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!recording?.id) return;

    // Use cached data immediately without re-fetching
    if (motionDataCache[recording.id]) {
      setMotionData(motionDataCache[recording.id]);
      setLoading(false);
      return;
    }

    const loadMotionData = async () => {
      try {
        setLoading(true);
        const response = await api.getMotionData(recording.id);
        const data = response.data?.data || [];
        cacheMotionData(recording.id, data);
        setMotionData(data);
      } catch (err) {
        console.error('Failed to load motion data:', err);
        setMotionData([]);
      } finally {
        setLoading(false);
      }
    };

    loadMotionData();
  }, [recording?.id]);

  if (loading) {
    return null;
  }

  // Generate SVG path data
  const generatePath = (data, key, maxVal) => {
    if (data.length === 0) return '';
    const metadata = getRecordingMetadata(recording);
    const duration = Number(metadata.duration ?? recording?.duration ?? 0);
    const hasTimedData = duration > 0 && data.some((point) => Number(point.time) > 0);
    
    const points = data.map((point, index) => {
      const x = hasTimedData
        ? Math.max(0, Math.min(100, (Number(point.time || 0) / duration) * 100))
        : (data.length > 1 ? (index / (data.length - 1)) * 100 : 0);
      const rawValue = Number(point[key] ?? 0);
      const value = Number.isFinite(rawValue) ? Math.max(0, Math.min(maxVal, rawValue)) : 0;
      const y = (MOTION_PLOT_HEIGHT - 1) - ((value / maxVal) * (MOTION_PLOT_HEIGHT - 3));
      return `${x},${y}`;
    });
    
    return `M${points.join(' L')}`;
  };

  const velPath = generatePath(motionData, 'vel', MOTION_VELOCITY_SCALE_MAX);
  const soundConfPath = generatePath(motionData, 'sound_conf', 1);
  const hasSoundConf = motionData.some((point) => Number(point.sound_conf ?? 0) > 0);

  return (
    <div className="reel-motion-plot" style={{
      width: '100%', 
      height: `${MOTION_PLOT_HEIGHT}px`,
      marginTop: '4px', 
      position: 'relative',
      background: 'rgba(255,255,255,0.1)',
      borderRadius: '2px',
      border: '1px solid rgba(255,255,255,0.1)'
    }}>
      <svg 
        width="100%" 
        height={MOTION_PLOT_HEIGHT}
        viewBox={`0 0 100 ${MOTION_PLOT_HEIGHT}`}
        preserveAspectRatio="none"
        style={{ display: 'block' }}
      >
        <path 
          d={velPath} 
          fill="none" 
          stroke={MOTION_COLORS?.velocity || '#009688'} 
          strokeWidth="0.6" 
          opacity="0.5"
        />
        {hasSoundConf && (
          <path
            d={soundConfPath}
            fill="none"
            stroke={MOTION_COLORS?.loudness || '#ff9800'}
            strokeWidth="0.55"
            opacity="0.72"
          />
        )}
      </svg>
    </div>
  );
};

/**
 * Chart visualization component for timeline metrics
 * Displays velocity data with interactive controls
 */
const ChartCard = React.memo(({
  row, 
  chartDate,
  handleTimelinePointClick,
  highlightedRecordingId,
  chartToggles,
  setChartToggles,
  timezoneOffset,
  MOTION_COLORS
}) => {
  const {
    chartMetrics,
    chartMaxWaiting,
    chartMaxActivity,
    chartMaxMotion,
    chartMaxDuration,
    chartMaxPerson,
    axisTicks,
    nowPercent,
  } = useMemo(
    () => buildDateMetricsData(row.recordings, chartDate, timezoneOffset),
    [chartDate, row.recordings, timezoneOffset],
  );

  const lineDefs = useMemo(() => {
    const buildSeriesPath = (valueExtractor, maxValue) => {
      if (!chartMetrics.length || maxValue <= 0) return '';

      const points = chartMetrics
        .map((metric) => {
          const value = valueExtractor(metric);
          if (value == null || !Number.isFinite(value)) return null;
          const normalized = Math.max(0, Math.min(1, value / maxValue));
          return `${metric.xPercent},${100 - (normalized * 100)}`;
        })
        .filter(Boolean);

      return points.length < 2 ? '' : `M ${points.join(' L ')}`;
    };

    return [
      { key: 'person', enabled: chartToggles.person, color: MOTION_COLORS.person, path: buildSeriesPath((metric) => metric.person, chartMaxPerson) },
      { key: 'duration', enabled: chartToggles.duration, color: MOTION_COLORS.duration, path: buildSeriesPath((metric) => metric.duration, chartMaxDuration) },
      { key: 'waiting', enabled: chartToggles.waiting, color: MOTION_COLORS.waiting, path: buildSeriesPath((metric) => metric.waiting, chartMaxWaiting) },
      { key: 'activity', enabled: chartToggles.activity, color: MOTION_COLORS.activity, path: buildSeriesPath((metric) => metric.activity, chartMaxActivity) },
      { key: 'motion', enabled: chartToggles.motion, color: MOTION_COLORS.motion, path: buildSeriesPath((metric) => metric.motion, chartMaxMotion) },
    ];
  }, [
    MOTION_COLORS,
    chartMaxActivity,
    chartMaxDuration,
    chartMaxMotion,
    chartMaxWaiting,
    chartMaxPerson,
    chartMetrics,
    chartToggles,
  ]);

  const metricControls = useMemo(() => [
    { key: 'person', label: metricConfig.labels.person, color: MOTION_COLORS.person },
    { key: 'duration', label: metricConfig.labels.duration, color: MOTION_COLORS.duration },
    { key: 'waiting', label: metricConfig.labels.waiting, color: MOTION_COLORS.waiting },
    { key: 'activity', label: metricConfig.labels.activity, color: MOTION_COLORS.activity },
    { key: 'motion', label: metricConfig.labels.motion, color: MOTION_COLORS.motion },
  ], [MOTION_COLORS]);

  return (
    <div className="camera-row-metrics-card">
      {/* Chart header with date nav and legend */}
      <div className="camera-row-metrics-header">
        {/* Legend toggles */}
        <div className="metrics-chart-controls">
          <div className="metrics-legend">
            {metricControls.map((ctrl) => (
              <label key={ctrl.key} className="metrics-legend-item">
                <input
                  type="checkbox"
                  checked={!!chartToggles[ctrl.key]}
                  onChange={(e) => setChartToggles(prev => ({ ...prev, [ctrl.key]: e.target.checked }))}
                  style={{ accentColor: ctrl.color, transform: 'scale(0.6)' }}
                />
                <span className="legend-dot" style={{ backgroundColor: ctrl.color }} />
                <span>{ctrl.label}</span>
              </label>
            ))}
          </div>
        </div>
      </div>

      {/* Line chart area */}
      <div 
        className="metrics-bar-chart" 
        role="img" 
        aria-label="Motion metrics by time of day"
        style={{ cursor: 'default', position: 'relative' }}
      >
        {/* Current time vertical red line */}
        {nowPercent != null && (
          <div style={{
            position: 'absolute', left: `${nowPercent}%`, top: 0, bottom: 0,
            width: 1, background: '#f44336', zIndex: 3, pointerEvents: 'none',
          }}>
            <div style={{ position: 'absolute', top: -1, left: -2, width: 5, height: 5, borderRadius: '50%', background: '#f44336' }} />
          </div>
        )}

        <svg
          width="100%"
          height="100%"
          viewBox="0 0 100 100"
          preserveAspectRatio="none"
          style={{ position: 'absolute', inset: 0, zIndex: 2, pointerEvents: 'none' }}
        >
          {lineDefs.filter((line) => line.enabled && line.path).map((line) => (
            <path
              key={line.key}
              d={line.path}
              fill="none"
              stroke={line.color}
              strokeWidth="0.6"
              strokeLinecap="round"
              strokeLinejoin="round"
              opacity="0.7"
              vectorEffect="non-scaling-stroke"
            />
          ))}
        </svg>

        {chartMetrics.map((metric) => {
          const markerHeights = [];
          if (chartToggles.person) markerHeights.push(Math.max(2, (metric.person / chartMaxPerson) * 100));
          if (chartToggles.duration) markerHeights.push(Math.max(2, (metric.duration / chartMaxDuration) * 100));
          if (chartToggles.waiting) markerHeights.push(Math.max(2, (metric.waiting / chartMaxWaiting) * 100));
          if (chartToggles.activity) markerHeights.push(Math.max(2, (metric.activity / chartMaxActivity) * 100));
          if (chartToggles.motion) markerHeights.push(Math.max(2, (metric.motion / chartMaxMotion) * 100));
          const markerHeight = markerHeights.length ? Math.max(...markerHeights) : 2;
          return (
            <button
              key={metric.id}
              type="button"
              className={`motion-point-btn${highlightedRecordingId === metric.id ? ' active' : ''}`}
              style={{ left: `${metric.xPercent}%`, bottom: `${Math.min(96, markerHeight + 2)}%` }}
              onClick={() => handleTimelinePointClick(row.cameraId, metric.id)}
              title={`${metric.timeLabel} | person: ${metric.person} | duration: ${metric.duration.toFixed(1)}s | waiting: ${metric.waiting.toFixed(2)} | activity: ${metric.activity.toFixed(2)} | motion: ${metric.motion.toFixed(2)}`}
            >
              <span className="point-dot" />
            </button>
          );
        })}
      </div>
      
      {/* Time axis: 00:00 to 24:00 */}
      <div className="metrics-time-axis">
        {axisTicks.map((tick, index) => (
          <div key={`tick-${index}`} className="metrics-axis-tick" style={{ left: `${tick.xPercent}%` }}>
            <span className="metrics-axis-mark" />
            {tick.showLabel && <span className={index === 0 ? 'metrics-axis-label-first' : 'metrics-axis-label'}>{tick.label}</span>}
          </div>
        ))}
      </div>
    </div>
  );
});

