export const RecordedWebRTCPlayer = ({
  recordingId,
  mode,
  clipController = null,
  active = true,
  overlay = false,
  allowMseFallback = false,
  allowHttpFallback = false,
  muted = false,
  controls = false,
  className = 'reel-video',
  setVideoRef,
  onPlaying,
  onEnded,
}) => {
  const videoRef = useRef(null);
  const [fallbackNotice, setFallbackNotice] = useState(null);
  const [protocolLabel, setProtocolLabel] = useState(null); // 'fl' | 'wr' | 'ms'
  const [isStarting, setIsStarting] = useState(active && mode === 'p2p');

  useEffect(() => {
    const video = videoRef.current;
    if (!active || !video || mode !== 'p2p') {
      if (video) video.srcObject = null;
      setIsStarting(false);
      setProtocolLabel(active ? 'fl' : null);
      return undefined;
    }
    setIsStarting(true);
    setProtocolLabel('wr');

    let cancelled = false;
    let ownedController = null;
    let noticeTimer = null;
    let mseProtocol = null;
    let msePlayer = null;
    let mseStarted = false;
    let directHttpActive = false;
    setFallbackNotice(null);

    const showFallbackNotice = (label, title) => {
      if (noticeTimer !== null) window.clearTimeout(noticeTimer);
      setFallbackNotice({ label, title });
      noticeTimer = window.setTimeout(() => {
        noticeTimer = null;
        setFallbackNotice(null);
      }, 1200);
    };

    const fallbackToDirectHttp = (failure) => {
      if (cancelled || directHttpActive) return;
      const reason = failure?.message || 'MSE playback failed';
      if (!allowHttpFallback) {
        msePlayer?.destroy();
        mseProtocol?.close();
        showFallbackNotice('err', reason);
        return;
      }
      directHttpActive = true;
      console.warn(`Raw MSE fallback failed: ${reason}; using direct HTTP`);
      msePlayer?.destroy();
      mseProtocol?.close();
      video.srcObject = null;
      video.src = api.getRecordingStreamUrl(recordingId, overlay);
      video.load();
      video.play().catch(() => {});
      showFallbackNotice('http', reason);
    };

    const fallbackToMse = async (failure) => {
      if (cancelled) return;
      const reason = failure?.message || 'WebRTC playback failed';
      const code = failure?.code || 'WEBRTC_PLAYBACK_FAILED';
      if (!allowMseFallback) {
        showFallbackNotice('err', reason);
        return;
      }
      console.warn(`P2P playback failed (${code}): ${reason}; using raw MSE`);
      try {
        await transportApi.reportClipHttpFallback(recordingId, code, reason);
      } catch (logError) {
        console.warn('Could not report P2P fallback to backend', logError);
      }
      if (cancelled) return;
      setProtocolLabel('ms');
      mseProtocol = new HttpClipProtocolClient(transportApi);
      msePlayer = new MseClipPlayer({
        protocol: mseProtocol,
        clipId: recordingId,
        videoElement: video,
        onState: ({ state, error: mseError }) => {
          if (state === 'failed' && mseStarted) {
            fallbackToDirectHttp(mseError);
          }
        },
      });
      try {
        await msePlayer.start();
        mseStarted = true;
      } catch (mseError) {
        fallbackToDirectHttp(mseError);
      }
    };

    const controller = clipController || createPersistentClipChannel();
    if (!clipController) ownedController = controller;
      controller.play({
        recordingId,
        overlay,
        videoElement: video,
      }).catch(fallbackToMse);

    return () => {
      cancelled = true;
      if (noticeTimer !== null) window.clearTimeout(noticeTimer);
      msePlayer?.destroy();
      mseProtocol?.close();
      if (ownedController) ownedController.close();
      else controller.detach(video);
      video.removeAttribute('src');
      video.load();
    };
  }, [active, allowHttpFallback, allowMseFallback, clipController, mode, overlay, recordingId]);

  return (
    <>
      <video
        ref={(element) => {
          videoRef.current = element;
          if (setVideoRef) setVideoRef(element);
        }}
        className={`${className} clip-adaptive-video`}
        muted={muted}
        controls={controls}
        playsInline
        autoPlay
        poster={api.getRecordingThumbnailUrl(recordingId)}
        onPlaying={(event) => {
          setIsStarting(false);
          onPlaying?.(event);
        }}
        onEnded={onEnded}
        onError={() => {
          setIsStarting(false);
          showRecordingPlaybackLimitToast(recordingId);
        }}
      />
      {isStarting && (
        <div className="clip-loading-overlay" role="status" aria-label="Loading clip">
          <Loader size={22} className="spin-icon" />
          <span>Loading clip…</span>
        </div>
      )}
      {fallbackNotice && (
        <div className="recording-webrtc-error" title={fallbackNotice.title}>
          {fallbackNotice.label}
        </div>
      )}
      {protocolLabel && (
        <div className={`clip-protocol-badge is-${protocolLabel}`}>{protocolLabel}</div>
      )}
    </>
  );
};

const formatSoundLoudness = (value) => {
  const numericValue = Number(value);
  if (!Number.isFinite(numericValue) || numericValue <= 0) return '';
  const scaled = numericValue <= 1 ? numericValue * 100 : numericValue;
  return scaled >= 10 ? `${Math.round(scaled)}` : scaled.toFixed(1);
};

const cleanSoundLabel = (value) => String(value || '')
  .replace(/\s*\[alert:\d+\]/, '')
  .replace(/\s*\[confidence:[^\]]+\]/, '')
  .replace(/^[^:]+:\s*/, '')
  .trim();

const formatSoundTooltip = (metadata) => {
  const labels = Array.isArray(metadata?.sound_labels) ? metadata.sound_labels : [];
  const candidates = labels
    .filter((item) => item && typeof item === 'object')
    .sort((a, b) => Number(b.score ?? 0) - Number(a.score ?? 0))
    .slice(0, 5)
    .map((item) => {
      const label = cleanSoundLabel(item.label || item.raw_label);
      if (!label) return null;
      const score = Number(item.score);
      const confidence = Number.isFinite(score)
        ? `${Math.round(Math.max(0, Math.min(1, score)) * 100)}%`
        : '';
      const loudness = formatSoundLoudness(item.loudness);
      const detail = [loudness, confidence].filter(Boolean).join('/');
      return detail ? `${label} (${detail})` : label;
    })
    .filter(Boolean);

  if (candidates.length > 0) return candidates.join('\n');
  return cleanSoundLabel(metadata?.sound_label);
};

const SOUND_LABEL_CONFIDENCE_CUTOFF = 0.1;
const SOUND_LABEL_MIN_INTENSITY = 0.35;

const getSoundLabelAppearance = (score) => {
  const numericScore = Number(score);
  if (!Number.isFinite(numericScore)) {
    return { visible: true, intensity: SOUND_LABEL_MIN_INTENSITY };
  }

  const confidence = Math.max(0, Math.min(1, numericScore));
  if (confidence < SOUND_LABEL_CONFIDENCE_CUTOFF) {
    return { visible: false, intensity: SOUND_LABEL_MIN_INTENSITY };
  }

  const normalized = (confidence - SOUND_LABEL_CONFIDENCE_CUTOFF)
    / (1 - SOUND_LABEL_CONFIDENCE_CUTOFF);
  return {
    visible: true,
    intensity: SOUND_LABEL_MIN_INTENSITY
      + ((1 - SOUND_LABEL_MIN_INTENSITY) * normalized),
  };
};

/**
 * Individual recording card component
 * Handles video playback, controls, and metadata display
 */
const ReelCard = ({
  recording,
  recordingIndex,
  row, 
  playingId, 
  expandedContext,
  playbackStatsById,
  playbackMode,
  clipController,
  allowMseFallback = false,
  allowHttpFallback = false,
  highlightedRecordingId,
  focusedRecordingId,
  labelMap,
  MOTION_COLORS,
  videoRefs,
  reelCardRefs,
  handleClick,
  handleOpenExpanded,
  handleVideoTimeUpdate,
  handleVideoLoadedMetadata,
  handleVideoEnded,
  handleSeekStart,
  handleSeekEnd,
  handleSeekChange,
  handleDownloadRecording,
  handleDeleteRecording,
  onToggleMark,
  timezoneOffset,
}) => {
  // Extract playback data for this recording
  const isPlaying = playingId === recording.id;
  const shouldLoadVideo = !expandedContext && isPlaying;
  const [videoLoading, setVideoLoading] = useState(false);
  const [thumbError, setThumbError] = useState(false);
  const [personView, setPersonView] = useState(false);
  const [personIndex, setPersonIndex] = useState(0);
  const [personState, setPersonState] = useState({ loading: false, loaded: false, error: '', persons: [] });
  const [changeView, setChangeView] = useState(false);
  const [heatmapView, setHeatmapView] = useState(false);
  const [heatmapError, setHeatmapError] = useState(false);
  const recordingMeta = getRecordingMetadata(recording);
  const notificationText = String(
    recordingMeta.text_log || recordingMeta.event_log || 'Movement detected'
  ).replace(/\s+/g, ' ').trim();
  const topSoundCandidate = getTopSoundLabel(recordingMeta);
  const soundAppearance = getSoundLabelAppearance(topSoundCandidate?.score);
  const topSound = soundAppearance.visible ? topSoundCandidate : null;
  const soundText = cleanSoundLabel(topSound?.label) || 'No sound detected';
  const soundScore = topSound?.score == null ? NaN : Number(topSound.score);
  const soundConfidence = Number.isFinite(soundScore)
    ? `${Math.round(Math.max(0, Math.min(1, soundScore)) * 100)}%`
    : '';
  const soundScoreText = Number.isFinite(soundScore)
    ? Math.max(0, Math.min(1, soundScore)).toFixed(2)
    : '';
  const soundDetail = [soundConfidence, soundScoreText].filter(Boolean).join(' · ');
  const soundDisplay = soundDetail ? `${soundDetail} · ${soundText}` : soundText;
  const soundTooltip = soundAppearance.visible
    ? (formatSoundTooltip(recordingMeta) || soundDisplay)
    : `No audio prediction above ${Math.round(SOUND_LABEL_CONFIDENCE_CUTOFF * 100)}% confidence`;
  const hasChange = !!recordingMeta.change_detection;
  const personCropCount = Math.max(0, Number(recordingMeta.person_crop_count ?? 0) || 0);
  const soundAlert = Number(recordingMeta.sound_alert ?? -1);
  const severityClass = (() => {
    // Legacy recording-data fallbacks can be removed after old metadata is migrated.
    const motionScore = Number(recordingMeta.motion_score ?? recordingMeta.fight_score ?? 0);
    const activityScore = Number(recordingMeta.activity_score ?? recordingMeta.burglary_score ?? 0);
    if (motionScore >= 0.7 || soundAlert >= 3) return ' reel-card-severe';
    if (activityScore >= 0.5 || soundAlert === 2) return ' reel-card-warning';
    if (Number(recordingMeta.max_person_count ?? 0) > 0 || soundAlert === 1) return ' reel-card-interest';
    return '';
  })();
  // videoVisible: true once the first frame is physically painted (onPlaying).
  // Using state (not ref) so hiding the thumbnail triggers a re-render at the
  // exact moment the video frame is on screen — removes the black-flash gap.
  const [videoVisible, setVideoVisible] = useState(false);
  const prevShouldLoad = useRef(false);
  const hasLoadedRef = useRef(false);
  const activeDetailView = personView ? 'people' : changeView ? 'change' : heatmapView ? 'heatmap' : 'video';
  const inlinePersons = personState.persons || [];
  const inlinePerson = inlinePersons[personIndex] || null;

  useEffect(() => {
    if (!personView || personState.loaded) return undefined;

    let cancelled = false;
    setPersonState((current) => ({ ...current, loading: true, error: '' }));
    api.getRecordingPersons(recording.id)
      .then((response) => {
        if (cancelled) return;
        const persons = Array.isArray(response.data?.persons) ? response.data.persons : [];
        setPersonIndex(0);
        setPersonState({ loading: false, loaded: true, error: '', persons });
      })
      .catch((error) => {
        if (cancelled) return;
        setPersonState({
          loading: false,
          loaded: true,
          error: error?.response?.data?.detail || 'Unable to load person crops',
          persons: [],
        });
      });

    return () => { cancelled = true; };
  }, [personState.loaded, personView, recording.id]);

  // Cache URLs — these are pure functions of recording.id / overlay flag and don't
  // change between renders, so memoising avoids function-call overhead on every render.
  const thumbUrl = useMemo(() => api.getRecordingThumbnailUrl(recording.id), [recording.id]);
  const heatmapUrl = useMemo(
    () => api.getRecordingThumbnailUrl(recording.id, 'heatmap'),
    [recording.id],
  );
  const streamUrl = useMemo(
    () => api.getRecordingStreamUrl(recording.id, false),
    [recording.id]
  );

  // Track when video src is set (loading starts) vs when it becomes playable.
  // Only raise the loading flag on the FIRST load; re-hovers skip spinner.
  useEffect(() => {
    if (shouldLoadVideo && !prevShouldLoad.current && playbackMode === 'file' && !hasLoadedRef.current) {
      setVideoLoading(true);
    }
    // If cursor leaves: reset both loading and visible so thumbnail shows again
    // on the next hover (src becomes undefined, browser resets the video element).
    if (!shouldLoadVideo) {
      setVideoLoading(false);
      setVideoVisible(false);
    }
    prevShouldLoad.current = shouldLoadVideo;
  }, [shouldLoadVideo, playbackMode]);

  const {
    timestampParts,
    playbackStats,
    playbackDuration,
    playbackProgress,
  } = getRecordingPlaybackViewData(recording, playbackStatsById[recording.id], timezoneOffset);

  return (
    <div
      key={recording.id}
      ref={(el) => {
        reelCardRefs.current[recording.id] = el;
      }}
      className={`reel-card${severityClass}${isPlaying ? ' reel-card-expanded' : ''}${highlightedRecordingId === recording.id ? ' reel-card-highlighted' : ''}${focusedRecordingId === recording.id ? ' reel-card-focused' : ''}`}
      onClick={() => handleClick(recording.id)}
    >
      {/* Notification and recording time */}
      <div className="reel-timestamp">
        <span
          className="reel-notification-top"
          title={notificationText}
          aria-label={notificationText}
        >
          <EventDescription text={notificationText} />
        </span>
        {timestampParts.time && <span className="reel-time">{timestampParts.time}</span>}
      </div>

      {/* Video thumbnail/player with controls */}
      <div className="reel-thumbnail">
        <span className="reel-number-badge">{recordingIndex + 1}</span>
        <button
          type="button"
          className="enlarge-btn"
          title={`Enlarge ${activeDetailView === 'video' ? 'playback' : activeDetailView}`}
          onClick={(event) => {
            event.stopPropagation();
            handleOpenExpanded(row.cameraId, recordingIndex, activeDetailView);
          }}
        >
          <Maximize2 size={14} />
        </button>

        {personView && (
          <div className="person-view-panel" onClick={(event) => event.stopPropagation()}>
            {personState.loading ? (
              <div className="analysis-view-state">
                <Loader size={18} className="spin-icon" />
                <span>Loading people…</span>
              </div>
            ) : personState.error ? (
              <div className="analysis-view-state error">{personState.error}</div>
            ) : inlinePerson ? (
              <>
                <button
                  type="button"
                  className="analysis-inline-nav prev"
                  disabled={personIndex === 0}
                  onClick={() => setPersonIndex((index) => Math.max(0, index - 1))}
                  title="Previous person"
                  aria-label="Previous person"
                >
                  <ChevronLeft size={16} />
                </button>
                <img
                  src={api.getPersonImageUrl(recording.id, inlinePerson.pid)}
                  alt={`Person ${personIndex + 1} from this clip`}
                />
                <span className="person-view-label">
                  Person {personIndex + 1} of {inlinePersons.length}
                </span>
                <button
                  type="button"
                  className="analysis-inline-nav next"
                  disabled={personIndex >= inlinePersons.length - 1}
                  onClick={() => setPersonIndex((index) => Math.min(inlinePersons.length - 1, index + 1))}
                  title="Next person"
                  aria-label="Next person"
                >
                  <ChevronRight size={16} />
                </button>
              </>
            ) : (
              <div className="analysis-view-state">No person images are available.</div>
            )}
          </div>
        )}

        {/* Change detection image panel (shown when changeView is active) */}
        {changeView && hasChange && (
          <div className="change-view-panel" onClick={(e) => e.stopPropagation()}>
            <img
              src={api.getRecordingChangeImageUrl(recording.id, 'diff')}
              alt="Detected changes drawn on the scene before motion"
              className="change-view-img"
            />
          </div>
        )}

        {heatmapView && !heatmapError && (
          <div className="heatmap-view-panel" onClick={(event) => event.stopPropagation()}>
            <img
              src={thumbUrl}
              alt=""
              className="heatmap-view-background"
            />
            <img
              src={heatmapUrl}
              alt="Active motion locations"
              className="heatmap-view-overlay"
              onError={() => {
                setHeatmapError(true);
                setHeatmapView(false);
                toast.error('Heatmap is not available for this clip');
              }}
            />
          </div>
        )}

        {/* Video/Stream player (hidden when an image analysis view is active) */}
        <div style={{ display: personView || (changeView && hasChange) || heatmapView ? 'none' : 'contents' }}>
        {playbackMode === 'file' ? (
          <>
            {/* Thumbnail: always in DOM so the switch from thumbnail→video happens
                in one atomic render (display:none toggle vs unmount/remount).
                Hiding via display:none is synchronous — no frame where neither is shown. */}
            {!thumbError && (
              <img
                src={thumbUrl}
                alt=""
                loading="lazy"
                style={{
                  position: 'absolute', top: 0, left: 0,
                  width: '100%', height: '100%',
                  objectFit: 'contain', zIndex: 4,
                  pointerEvents: 'none',
                  display: videoVisible ? 'none' : 'block',
                }}
                onLoad={fitReelToMediaAspectRatio}
                onError={() => setThumbError(true)}
              />
            )}
            <video
            ref={(el) => (videoRefs.current[recording.id] = el)}
            className="reel-video"
            src={shouldLoadVideo ? streamUrl : undefined}
            muted
            playsInline
            preload="none"
            autoPlay={shouldLoadVideo}
            onLoadedMetadata={(event) => {
              fitReelToMediaAspectRatio(event);
              handleVideoLoadedMetadata(recording.id, event);
            }}
            onTimeUpdate={(event) => handleVideoTimeUpdate(recording.id, event)}
            onLoadedData={() => setVideoLoading(false)}
            onCanPlay={() => setVideoLoading(false)}
            onPlaying={() => { hasLoadedRef.current = true; setVideoVisible(true); setVideoLoading(false); }}
            onEnded={() => handleVideoEnded(recording.id)}
            onError={(e) => {
              console.error('Video error:', recording.id, e);
              setVideoLoading(false);
              showRecordingPlaybackLimitToast(recording.id);
            }}
          />
          </>
        ) : (
          <>
            {!thumbError && !videoVisible && (
              <img
                src={thumbUrl}
                alt=""
                loading="lazy"
                style={{
                  position: 'absolute', top: 0, left: 0,
                  width: '100%', height: '100%', objectFit: 'contain', zIndex: 4,
                  pointerEvents: 'none',
                }}
                onLoad={fitReelToMediaAspectRatio}
                onError={() => setThumbError(true)}
              />
            )}
            <RecordedWebRTCPlayer
              recordingId={recording.id}
              mode={playbackMode}
              clipController={clipController}
              active={shouldLoadVideo}
              overlay={false}
              allowMseFallback={allowMseFallback}
              allowHttpFallback={allowHttpFallback}
              muted
              setVideoRef={(element) => { videoRefs.current[recording.id] = element; }}
              onPlaying={() => setVideoVisible(true)}
              onEnded={() => handleVideoEnded(recording.id)}
            />
          </>
        )}
        </div>

        {isPlaying && !personView && !changeView && !heatmapView && (
          <div className="pause-indicator">
            <Pause size={24} />
          </div>
        )}

        {videoLoading && playbackMode === 'file' && !recording.metadata?.browser_ready && (
          <div className="transcode-overlay">
            <Loader size={22} className="spin-icon" />
            <span>Converting…</span>
          </div>
        )}
      </div>

      {/* Recording info panel with controls and metadata */}
      <div className="reel-info">
        {/* Playback controls */}
        <div className="reel-playback-controls">
          <div className="reel-progress-header">
            <div className="reel-progress-left">
              <div className="reel-sound-log" title={soundTooltip}>
                <Volume2 size={9} strokeWidth={2.3} aria-hidden="true" />
                {soundDetail && <span className="reel-sound-values">{soundDetail}</span>}
                <span
                  className="reel-sound-prediction sound-confidence-label"
                  style={{ '--sound-confidence-intensity': soundAppearance.intensity }}
                >
                  {soundText}
                </span>
              </div>
            </div>
          </div>
        </div>

        <div className="reel-card-details">
          <div className="reel-detail-playback" onClick={(event) => event.stopPropagation()}>
          <input
            type="range"
            min={0}
            max={Math.max(playbackDuration, 0.01)}
            step={0.01}
            value={Math.min(playbackStats.currentTime, Math.max(playbackDuration, 0.01))}
            disabled={playbackMode !== 'file'}
            onMouseDown={() => handleSeekStart(recording.id, false)}
            onMouseUp={() => handleSeekEnd(recording.id)}
            onTouchStart={() => handleSeekStart(recording.id, false)}
            onTouchEnd={() => handleSeekEnd(recording.id)}
            onChange={(event) => handleSeekChange(recording.id, event.target.value)}
            className="reel-progress-slider"
            style={{ '--progress': `${playbackProgress}%` }}
          />
          <SimpleMotionPlot recording={recording} MOTION_COLORS={MOTION_COLORS} />
          </div>
        
        {/* Recording metadata and actions */}
        <div className="reel-meta-row">
          <div className="reel-card-actions" onClick={(event) => event.stopPropagation()}>
            <label className="reel-mark-toggle" title="Mark recording">
              <input
                aria-label="Mark recording"
                type="checkbox"
                checked={!!labelMap[recording.id]}
                onChange={() => onToggleMark(recording.id)}
              />
            </label>
            {personCropCount > 0 && (
              <button
                type="button"
                className={`reel-action-btn${personView ? ' active' : ''}`}
                title={personView ? 'Show video clip' : `View ${personCropCount} person ${personCropCount === 1 ? 'crop' : 'crops'}`}
                aria-label={personView ? 'Show video clip' : `View ${personCropCount} person ${personCropCount === 1 ? 'crop' : 'crops'}`}
                onClick={() => {
                  setChangeView(false);
                  setHeatmapView(false);
                  setPersonView((active) => !active);
                }}
                style={personView ? { background: '#00897b', color: '#fff', borderColor: '#00897b' } : {}}
              >
                <User size={12} />
              </button>
            )}
            <button
              type="button"
              className={`reel-action-btn${heatmapView ? ' active' : ''}`}
              title={heatmapView ? 'Show video clip' : 'Active motion locations'}
              aria-label={heatmapView ? 'Show video clip' : 'Active motion locations'}
              onClick={(event) => {
                event.stopPropagation();
                setPersonView(false);
                setChangeView(false);
                setHeatmapError(false);
                setHeatmapView((active) => !active);
              }}
              style={heatmapView ? { background: '#ef6c00', color: '#fff', borderColor: '#ef6c00' } : {}}
            >
              <MapPin size={12} />
            </button>
            {hasChange && (
              <ChangeButton
                isActive={changeView}
                onClick={(e) => {
                  e.stopPropagation();
                  setPersonView(false);
                  setHeatmapView(false);
                  setChangeView((v) => !v);
                }}
              />
            )}
            <button
              type="button"
              className="reel-action-btn"
              title="Download"
              onClick={() => handleDownloadRecording(recording.id)}
            >
              <Download size={12} />
            </button>
            <button
              type="button"
              className="reel-action-btn danger"
              title="Delete"
              onClick={() => handleDeleteRecording(recording.id)}
            >
              <Trash2 size={12} />
            </button>
          </div>
        </div>
        </div>
      </div>
    </div>
  );
};

/**
 * Build thumbnail candidates array from recording metadata.
 * Returns array of { type, label, color } objects.
 */
const buildThumbnailCandidates = (recording) => {
  const candidates = [
    { type: 'main', label: 'Clip Start', color: '#78909c' }  // Gray
  ];
  
  const meta = getRecordingMetadata(recording);
  if (!meta) return candidates;
  
  // Add audio alert peak if available
  if (meta.max_audio_alert_timestamp !== undefined && meta.max_audio_alert_timestamp > 0) {
    candidates.push({
      type: 'audio',
      label: 'Audio Alert',
      color: '#ab47bc'  // Purple for audio
    });
  }
  
  return candidates;
};

const LogColumnLabel = ({ icon: Icon, label, className = '' }) => (
  <div className={`transpose-label-row${className ? ` ${className}` : ''}`} title={label} aria-label={label} tabIndex={0}>
    <Icon size={13} strokeWidth={2.2} aria-hidden="true" />
    <span className="transpose-label-text">{label}</span>
  </div>
);

const getRecordingTextLog = (metadata) => (
  String(metadata?.text_log || metadata?.event_log || '').trim()
);

const EVENT_ACTION_ICONS = {
  entered: LogIn,
  exited: LogOut,
  waiting: Hourglass,
  active: Footprints,
  'moving fast': Zap,
};

const EventDescription = ({ text }) => {
  const match = String(text || '').match(
    /^(Person|Someone)\s+(entered|exited|waiting|active|moving fast)(?::\s*(.+))?$/i,
  );
  if (!match) return text || 'No description';

  const [, subject, action, duration] = match;
  const SubjectIcon = subject.toLowerCase() === 'person' ? User : Move;
  const ActionIcon = EVENT_ACTION_ICONS[action.toLowerCase()];
  return (
    <span className="event-description">
      <span
        className="event-description-icon"
        role="img"
        aria-label={subject}
      >
        <SubjectIcon size={13} aria-hidden="true" />
      </span>
      <span
        className="event-description-icon"
        role="img"
        aria-label={action}
      >
        <ActionIcon size={13} aria-hidden="true" />
      </span>
      {duration ? <span className="event-description-duration">{duration}</span> : null}
    </span>
  );
};

const formatScorePercent = (value) => {
  const numericValue = Number(value);
  if (!Number.isFinite(numericValue) || numericValue <= 0) return null;
  return `${Math.max(0, Math.min(100, Math.round(numericValue * 100)))}%`;
};

const formatScoreOutOfFive = (value) => {
  const numericValue = Number(value);
  if (!Number.isFinite(numericValue) || numericValue <= 0) return null;
  return `${Math.max(0, Math.min(5, Math.round(numericValue * 5)))}/5`;
};

const formatChangePercent = (value) => {
  const numericValue = Number(value);
  if (!Number.isFinite(numericValue) || numericValue <= 0) return null;
  if (numericValue < 1) return '<1%';
  return `${Math.round(numericValue)}%`;
};

const formatWaitingTime = (value) => {
  const seconds = Number(value);
  if (!Number.isFinite(seconds) || seconds <= 0) return null;
  if (seconds < 60) return `${Math.round(seconds)}s`;
  return `${Math.round(seconds / 60)}m`;
};

const READ_LOG_STORAGE_KEY = 'nvr_read_event_logs';
const MAX_READ_LOGS = 1000;

const getStoredReadLogs = () => {
  if (typeof window === 'undefined') return {};
  try {
    return JSON.parse(window.localStorage.getItem(READ_LOG_STORAGE_KEY) || '{}') || {};
  } catch (error) {
    return {};
  }
};

const getRelativeTime = (date) => {
  if (!date) return '';
  const now = new Date();
  const diffMs = now - date;
  const diffSecs = Math.floor(diffMs / 1000);
  const diffMins = Math.floor(diffSecs / 60);
  const diffHours = Math.floor(diffMins / 60);
  if (diffHours > 0) return `${diffHours}h`;
  if (diffMins > 0) return `${diffMins}m`;
  if (diffSecs > 0) return `${diffSecs}s`;
  return '';
};

