  chartDate,
  highlightedRecordingId,
  markedIds,
  onToggleMark,
  showMarkedOnly,
  setShowMarkedOnly,
  markedCount,
  showAllEvents,
  setShowAllEvents,
  getTodayLocal,
  shiftDate,
  timezoneOffset,
