import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import EventMetricsChart from './MotionActivityChart';
import ResourceUsageChart from './ResourceUsageChart';
import { api } from '../../api';
import { normalizeTimezone } from '../EventView/EventViewUtils';
import zonesApi from '../../zonesApi';
import './Dashboard.css';

const Dashboard = ({
  cameras,
  recordings,
  systemInfo,
  ensureRecordings,
  recordingPagination = {},
  onLoadMoreRecordings,
}) => {
  const navigate = useNavigate();
  const [allZones, setAllZones] = useState([]);
  const [serverTimezone, setServerTimezone] = useState(() => normalizeTimezone(null));

  useEffect(() => {
    ensureRecordings?.().catch((error) => {
      console.error('Failed to load dashboard recordings:', error);
    });
  }, [ensureRecordings]);

  useEffect(() => {
    zonesApi.getZonesSummary()
      .then((res) => {
        const flat = [];
        Object.entries(res.data || {}).forEach(([cameraId, data]) => {
          (data.zones || []).forEach((z) => flat.push({ ...z, camera_id: cameraId, camera_name: data.camera_name }));
        });
        setAllZones(flat);
      })
      .catch(() => {});
  }, []);

  // Fetch server timezone
  useEffect(() => {
    let cancelled = false;
    const loadServerTimezone = async () => {
      try {
        const tzInfo = await api.getServerTimezone();
        if (cancelled) return;
        setServerTimezone(normalizeTimezone(tzInfo));
      } catch (_err) {
        console.warn('Failed to load server timezone:', _err);
        if (!cancelled) {
          setServerTimezone(normalizeTimezone(null));
        }
      }
    };
    loadServerTimezone();
    return () => {
      cancelled = true;
    };
  }, []);

  const normalizedProcessUsage = systemInfo.process_usage || systemInfo.process || {};
  const normalizedAverages = systemInfo.averages_5m || {};
  const normalizedAiUsage = systemInfo.ai_process_usage || {};
  const normalizedAudioAiUsage = systemInfo.audio_ai_process_usage || {};
  const normalizedMultiplexerUsage = systemInfo.multiplexer_usage || {};
  const normalizedDiskSize = systemInfo.disk_size || {};
  const processPidLabel = normalizedProcessUsage.pid ?? 'N/A';
  const multiplexerPidLabel = normalizedMultiplexerUsage.pid ?? 'N/A';

  const formatPercent3 = (value) => {
    const numeric = Number(value);
    if (!Number.isFinite(numeric)) return '0.000%';
    return `${numeric.toFixed(3)}%`;
  };

  const formatMB = (value) => {
    const numeric = Number(value);
    if (!Number.isFinite(numeric)) return '0.0 MB';
    return `${numeric.toFixed(1)} MB`;
  };

  const formatIO = (value) => {
    const numeric = Number(value);
    if (!Number.isFinite(numeric)) return '0.0 MB';
    if (numeric >= 1024) {
      return `${(numeric / 1024).toFixed(2)} GB`;
    }
    return `${numeric.toFixed(1)} MB`;
  };

  const formatRate = (value) => {
    const numeric = Number(value);
    if (!Number.isFinite(numeric)) return '0.00 MB/s';
    return `${numeric.toFixed(2)} MB/s`;
  };

  return (
    <div>
      <div className="page-header">
        <h1 className="page-title">Dashboard</h1>
        <p className="page-subtitle">System overview and statistics</p>
      </div>

      {/* Event metrics chart */}
      <div className="content-section" style={{ marginBottom: 16 }}>
        <div className="section-header">
          <h2 className="section-title">24h Event Metrics</h2>
        </div>
        <EventMetricsChart recordings={recordings} cameras={cameras} allZones={allZones} onDayClick={(date, recordingId, cameraId) => navigate('/live', { state: { date, recordingId, cameraId } })} />
      </div>

      {/* CPU & Memory Usage Chart */}
      <div className="content-section" style={{ marginBottom: 16 }}>
        <div className="section-header">
          <h2 className="section-title">24h CPU &amp; Memory Usage</h2>
        </div>
        <ResourceUsageChart serverTimezone={serverTimezone} />
      </div>

      <div className="content-section">
        <div className="section-header">
          <h2 className="section-title">
            System Metrics <span className="section-title-subtle">(PID: {processPidLabel})</span>
          </h2>
        </div>

        <div className="camera-info-grid">
          <div className="camera-info-card">
            <div className="camera-info-header">
              <div className="camera-details">
                <div className="camera-name">Overall System</div>
              </div>
            </div>
            <div className="camera-metadata">
              <div className="metadata-item">
                <span className="metadata-label">CPU Usage:</span>
                <span className="metadata-value">{formatPercent3(normalizedAverages.cpu_usage)}</span>
              </div>
              <div className="metadata-item">
                <span className="metadata-label">RAM Usage:</span>
                <span className="metadata-value">{formatPercent3(normalizedAverages.memory_usage)}</span>
              </div>
              <div className="metadata-item">
                <span className="metadata-label">Disk IO:</span>
                <span className="metadata-value">R {formatRate(normalizedAverages.disk_io_read_mb_s)} / W {formatRate(normalizedAverages.disk_io_write_mb_s)}</span>
              </div>
              <div className="metadata-item">
                <span className="metadata-label">Disk Size:</span>
                <span className="metadata-value">{formatIO(normalizedDiskSize.overall_used_gb * 1024)} / {formatIO(normalizedDiskSize.overall_total_gb * 1024)}</span>
              </div>
            </div>
          </div>

          <div className="camera-info-card">
            <div className="camera-info-header">
              <div className="camera-details">
                <div className="camera-name">Server ({processPidLabel})</div>
              </div>
            </div>
            <div className="camera-metadata">
              <div className="metadata-item">
                <span className="metadata-label">CPU Usage:</span>
                <span className="metadata-value">{formatPercent3(normalizedAverages.process_cpu_percent)}</span>
              </div>
              <div className="metadata-item">
                <span className="metadata-label">RAM Usage:</span>
                <span className="metadata-value">{formatPercent3(normalizedAverages.process_memory_percent)} ({formatMB(normalizedProcessUsage.memory_mb)})</span>
              </div>
              <div className="metadata-item">
                <span className="metadata-label">Disk IO:</span>
                <span className="metadata-value">R {formatRate(normalizedAverages.process_disk_io_read_mb_s)} / W {formatRate(normalizedAverages.process_disk_io_write_mb_s)}</span>
              </div>
              <div className="metadata-item">
                <span className="metadata-label">Disk Size (Rec Dir):</span>
                <span className="metadata-value">{formatIO((normalizedDiskSize.recording_dir_size_gb) * 1024)}</span>
              </div>
            </div>
          </div>

          <div className="camera-info-card">
            <div className="camera-info-header">
              <div className="camera-details">
                <div className="camera-name">Vision AI ({normalizedAiUsage.mode ?? 'N/A'})</div>
              </div>
            </div>
            <div className="camera-metadata">
              <div className="metadata-item">
                <span className="metadata-label">CPU Usage:</span>
                <span className="metadata-value">{formatPercent3(normalizedAverages.ai_cpu_percent)}</span>
              </div>
              <div className="metadata-item">
                <span className="metadata-label">RAM Usage:</span>
                <span className="metadata-value">{formatPercent3(normalizedAverages.ai_memory_percent)} ({formatMB(normalizedAiUsage.memory_mb ?? 0)})</span>
              </div>
              <div className="metadata-item">
                <span className="metadata-label">PIDs:</span>
                <span className="metadata-value">
                  {(normalizedAiUsage.tracker_count ?? 0) > 0
                    ? normalizedAiUsage.tracker_pids.join(', ')
                    : 'N/A'}
                </span>
              </div>
              <div className="metadata-item">
                <span className="metadata-label">Trackers:</span>
                <span className="metadata-value">{normalizedAiUsage.tracker_count ?? 0}</span>
              </div>
            </div>
          </div>

          <div className="camera-info-card">
            <div className="camera-info-header">
              <div className="camera-details">
                <div className="camera-name">Audio AI ({normalizedAudioAiUsage.mode ?? 'N/A'})</div>
              </div>
            </div>
            <div className="camera-metadata">
              <div className="metadata-item">
                <span className="metadata-label">CPU Usage:</span>
                <span className="metadata-value">{formatPercent3(normalizedAverages.audio_ai_cpu_percent)}</span>
              </div>
              <div className="metadata-item">
                <span className="metadata-label">RAM Usage:</span>
                <span className="metadata-value">{formatPercent3(normalizedAverages.audio_ai_memory_percent)} ({formatMB(normalizedAudioAiUsage.memory_mb ?? 0)})</span>
              </div>
              <div className="metadata-item">
                <span className="metadata-label">PIDs:</span>
                <span className="metadata-value">
                  {(normalizedAudioAiUsage.analyzer_count ?? 0) > 0
                    ? normalizedAudioAiUsage.analyzer_pids.join(', ')
                    : 'N/A'}
                </span>
              </div>
              <div className="metadata-item">
                <span className="metadata-label">PANN Detection:</span>
                <span className="metadata-value">{normalizedAudioAiUsage.enable_pann != null ? (normalizedAudioAiUsage.enable_pann ? 'Enabled' : 'Disabled') : 'N/A'}</span>
              </div>
            </div>
          </div>

          {normalizedMultiplexerUsage.running && (
            <div className="camera-info-card">
              <div className="camera-info-header">
                <div className="camera-details">
                  <div className="camera-name">Multiplexer ({multiplexerPidLabel})</div>
                </div>
              </div>
              <div className="camera-metadata">
                <div className="metadata-item">
                  <span className="metadata-label">CPU Usage:</span>
                  <span className="metadata-value">{formatPercent3(normalizedAverages.multiplexer_cpu_percent)}</span>
                </div>
                <div className="metadata-item">
                  <span className="metadata-label">RAM Usage:</span>
                  <span className="metadata-value">{formatPercent3(normalizedAverages.multiplexer_memory_percent)} ({formatMB(normalizedMultiplexerUsage.memory_mb)})</span>
                </div>
                <div className="metadata-item">
                  <span className="metadata-label">Process:</span>
                  <span className="metadata-value">{normalizedMultiplexerUsage.name || 'go2rtc'}</span>
                </div>
                <div className="metadata-item">
                  <span className="metadata-label">Status:</span>
                  <span className="metadata-value">Running</span>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>

      {recordingPagination.hasMore && (
        <div style={{ display: 'flex', justifyContent: 'center', margin: '18px 0' }}>
          <button
            type="button"
            className="btn btn-secondary"
            disabled={recordingPagination.loading}
            onClick={() => onLoadMoreRecordings?.().catch((error) => {
              console.error('Failed to load older dashboard recordings:', error);
            })}
          >
            {recordingPagination.loading
              ? 'Loading...'
              : `Load older history (${recordingPagination.loaded}/${recordingPagination.total})`}
          </button>
        </div>
      )}

    </div>
  );
};

export default Dashboard;
